// ---------------------------------------------------------------------------
// Admin builder + route registration
// ---------------------------------------------------------------------------

type ModelRegistrar = Box<dyn FnOnce(Router, &Db, Arc<Vec<AdminEntry>>) -> Router + Send + Sync>;

/// Builder that collects admin models and mounts them with a shared
/// `/admin` index page.
pub struct Admin {
    entries: Vec<AdminEntry>,
    registrars: Vec<ModelRegistrar>,
}

impl Admin {
    pub fn new() -> Self {
        Self {
            entries: vec![USER_ENTRY.clone()],
            registrars: Vec::new(),
        }
    }

    /// Register a user-facing model on this admin.
    pub fn model<T: AdminModel>(mut self) -> Self {
        self.entries.push(AdminEntry {
            admin_name: T::ADMIN_NAME,
            display_name: T::DISPLAY_NAME,
            singular_name: T::singular_name(),
            table: T::TABLE,
            fields: T::FIELDS,
            core: false,
        });
        self.registrars.push(Box::new(|router, db, entries| {
            mount_model::<T>(router, db, entries)
        }));
        self
    }

    /// Number of user-registered models (not counting core models).
    pub fn len(&self) -> usize {
        self.entries.iter().filter(|e| !e.core).count()
    }

    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }

    /// All entries, including core models. Used by the schema exporter;
    /// iterate with `.iter().filter(|e| !e.core)` when you want only
    /// user-facing models.
    pub fn entries(&self) -> &[AdminEntry] {
        &self.entries
    }

    /// Mount the admin onto a router.
    pub fn register(self, mut router: Router, db: &Db) -> Router {
        let entries = Arc::new(self.entries);

        // Error shell: catch unhandled NotFound / Internal errors that
        // come out of `/admin/*` handlers and render them in-shell.
        // Public (non-admin) paths fall through to the router default.
        let err_entries = entries.clone();
        router = router.wrap(move |req, next| {
            let entries = err_entries.clone();
            async move {
                let is_admin = req.uri().path().starts_with("/admin");
                if !is_admin {
                    return next.run(req).await;
                }
                // Skip the stylesheet and favicon — neither is HTML
                // and neither should ever render a shell page on a
                // 404 / 500 from an upstream handler.
                let path = req.uri().path();
                if path == "/admin/assets/admin.css" || path == "/admin/assets/favicon.svg" {
                    return next.run(req).await;
                }
                let user_email = req
                    .ctx()
                    .get::<crate::auth::Identity>()
                    .map(|i| i.email.clone());
                let csrf = req
                    .ctx()
                    .get::<crate::auth::CsrfToken>()
                    .map(|t| t.0.clone());

                let res = next.run(req).await;
                match res {
                    Err(Error::NotFound) => Ok(admin_not_found_response(
                        &entries,
                        user_email.as_deref(),
                        csrf.as_deref(),
                    )),
                    Err(Error::Internal(msg)) => {
                        let req_id = new_request_id();
                        eprintln!("admin 500 [{req_id}]: {msg}");
                        Ok(admin_server_error_response(
                            &entries,
                            user_email.as_deref(),
                            csrf.as_deref(),
                            &req_id,
                        ))
                    }
                    other => other,
                }
            }
        });

        // Static asset: framework-owned stylesheet. Cached for an hour
        // because the bytes are pinned to the compiled binary — the
        // content can only change with a redeploy.
        router = router.get("/admin/assets/admin.css", |_req, _params| async move {
            Ok::<Response, Error>(admin_css_response())
        });
        // Favicon — scalable SVG served from the same /admin/assets
        // namespace. No binary asset, no external dependency, full
        // brand colouring. Requested by every browser tab.
        router = router.get("/admin/assets/favicon.svg", |_req, _params| async move {
            Ok::<Response, Error>(admin_favicon_response())
        });

        // 0.10+ bundled assets for the template-based admin. Served
        // under the new `/admin/static/…` namespace (the legacy
        // `/admin/assets/` routes above keep working for the
        // pre-template pages until stage 5 removes them).
        for &(path, content_type, bytes) in crate::admin::templating::BUNDLED_ASSETS {
            let full_path = format!("/admin/static/{path}");
            router = router.get(&full_path, move |_req, _params| async move {
                Ok::<Response, Error>(bundled_asset_response(bytes, content_type))
            });
        }

        // Build the AdminUiModel registry first — both the dashboard
        // (GET /admin) and the per-model routes (/admin/:model and
        // its create/edit/delete variants) read from it.
        let admin_new_registry = std::sync::Arc::new({
            let mut reg = crate::admin::admin_form_bridge::AdminRegistry::new();
            reg.register("users", crate::admin::layout::new_user_admin);
            reg
        });

        // GET /admin — dashboard rendered by the new admin engine
        // (one card per registered AdminUiModel). Uses the same shell
        // / topbar / sidebar / CSS as the per-model pages so the
        // visual identity stays consistent across the admin surface.
        let index_db = db.clone();
        let index_registry = admin_new_registry.clone();
        let index_entries = entries.clone();
        router = router.get("/admin", move |req, _params| {
            let db = index_db.clone();
            let registry = index_registry.clone();
            let legacy_entries = index_entries.clone();
            async move {
                if let Err(resp) = admin_guard(req.ctx()) {
                    return Ok(resp);
                }
                // 0.10+ template render. Identity is cloned out of the
                // request context so the borrow ends before the async
                // `dashboard_render` awaits on DB queries.
                let identity = crate::auth::identity(req.ctx()).cloned();
                let csrf = ctx_csrf(req.ctx()).map(str::to_string);
                let html = crate::admin::layout::dashboard_render(
                    &db,
                    &registry,
                    legacy_entries.as_slice(),
                    identity.as_ref(),
                    csrf.as_deref(),
                )
                .await;
                Ok::<Response, Error>(with_admin_headers(crate::http::html(html)))
            }
        });
        // Login + logout. Unauthenticated users *need* to reach
        // /admin/login; POST /admin/logout is CSRF-protected inside
        // the handler. GET /admin/logout is **public** — Django uses
        // it both for the "confirm sign out" prompt (when a session
        // is live) and for the post-logout "you have signed out"
        // page (after POST clears the session).
        let login_db = db.clone();
        router = router.post("/admin/login", move |req, _params| {
            let db = login_db.clone();
            async move { handle_login(req, &db).await }
        });
        // Direct GET to /admin/login: bookmarks, browser history, dev
        // probes, or any link that hits the login URL straight (instead
        // of bouncing through the unauthenticated /admin redirect).
        // Renders the same login form as the 401 fallback so the page
        // never dead-ends with a 405. If the request is already
        // authenticated, hand them the standard login page anyway —
        // they can ignore it or sign out from there.
        router = router.get("/admin/login", |_req, _params| async move {
            Ok::<Response, Error>(login_page(200, None, None))
        });
        let logout_db = db.clone();
        router = router.post("/admin/logout", move |req, _params| {
            let db = logout_db.clone();
            async move { handle_logout(req, &db).await }
        });
        // "Sign out other sessions" from the account page.
        let sessions_db = db.clone();
        router = router.post("/admin/sessions/clear", move |req, _params| {
            let db = sessions_db.clone();
            async move { handle_clear_other_sessions(req, &db).await }
        });
        router = router.get("/admin/logout", move |req, _params| async move {
            let signed_in = req.ctx().get::<crate::auth::Identity>().is_some();
            let csrf = ctx_csrf(req.ctx()).map(str::to_string);
            Ok::<Response, Error>(logout_confirmation_response(signed_in, csrf.as_deref()))
        });

        // i18n L4a — set the signed-in user's UI language preference
        // (per-user; never mutates a ViewSpec). CSRF-protected POST.
        let lang_db = db.clone();
        router = router.post("/admin/language", move |req, _params| {
            let db = lang_db.clone();
            async move { admin_language_post(req, &db).await }
        });

        // Password change (self-service). GET renders the form, POST
        // validates + rotates the hash + re-issues the session cookie.
        let pw_get_entries = entries.clone();
        let pw_get_db = db.clone();
        let pw_get_registry = admin_new_registry.clone();
        router = router.get("/admin/password_change", move |req, _params| {
            let legacy_entries = pw_get_entries.clone();
            let db = pw_get_db.clone();
            let registry = pw_get_registry.clone();
            async move {
                if let Err(resp) = admin_guard(req.ctx()) {
                    return Ok(resp);
                }
                let identity = crate::auth::identity(req.ctx()).cloned();
                let csrf = ctx_csrf(req.ctx()).map(str::to_string);
                let html = crate::admin::layout::password_change_render(
                    &db,
                    &registry,
                    &legacy_entries,
                    identity.as_ref(),
                    csrf.as_deref(),
                    None,
                )
                .await;
                Ok::<Response, Error>(with_admin_headers(crate::http::html(html)))
            }
        });
        let pw_post_entries = entries.clone();
        let pw_post_db = db.clone();
        let pw_post_registry = admin_new_registry.clone();
        router = router.post("/admin/password_change", move |req, _params| {
            let legacy_entries = pw_post_entries.clone();
            let db = pw_post_db.clone();
            let registry = pw_post_registry.clone();
            async move {
                if let Err(resp) = admin_guard(req.ctx()) {
                    return Ok(resp);
                }
                handle_password_change_post(req, &db, &registry, &legacy_entries).await
            }
        });
        let pw_done_entries = entries.clone();
        let pw_done_db = db.clone();
        let pw_done_registry = admin_new_registry.clone();
        router = router.get("/admin/password_change/done", move |req, _params| {
            let legacy_entries = pw_done_entries.clone();
            let db = pw_done_db.clone();
            let registry = pw_done_registry.clone();
            async move {
                if let Err(resp) = admin_guard(req.ctx()) {
                    return Ok(resp);
                }
                let identity = crate::auth::identity(req.ctx()).cloned();
                let csrf = ctx_csrf(req.ctx()).map(str::to_string);
                let html = crate::admin::layout::password_change_done_render(
                    &db,
                    &registry,
                    &legacy_entries,
                    identity.as_ref(),
                    csrf.as_deref(),
                )
                .await;
                Ok::<Response, Error>(with_admin_headers(crate::http::html(html)))
            }
        });

        // Profile (self-service identity card).
        let profile_entries = entries.clone();
        let profile_db = db.clone();
        let profile_registry = admin_new_registry.clone();
        router = router.get("/admin/profile", move |req, _params| {
            let legacy_entries = profile_entries.clone();
            let db = profile_db.clone();
            let registry = profile_registry.clone();
            async move {
                if let Err(resp) = admin_guard(req.ctx()) {
                    return Ok(resp);
                }
                let identity = crate::auth::identity(req.ctx()).cloned();
                let csrf = ctx_csrf(req.ctx()).map(str::to_string);
                let user = match identity.as_ref() {
                    Some(id) => crate::auth::user::find_by_id(&db, id.user_id).await?,
                    None => None,
                };
                let html = crate::admin::layout::profile_render(
                    &db,
                    &registry,
                    &legacy_entries,
                    identity.as_ref(),
                    user.as_ref(),
                    csrf.as_deref(),
                )
                .await;
                Ok::<Response, Error>(with_admin_headers(crate::http::html(html)))
            }
        });

        // Recent actions (project-wide audit timeline).
        let actions_entries = entries.clone();
        let actions_db = db.clone();
        let actions_registry = admin_new_registry.clone();
        router = router.get("/admin/actions", move |req, _params| {
            let legacy_entries = actions_entries.clone();
            let db = actions_db.clone();
            let registry = actions_registry.clone();
            async move {
                if let Err(resp) = admin_guard(req.ctx()) {
                    return Ok(resp);
                }
                let query = req.query();
                let model_filter = query
                    .get("model")
                    .map(str::trim)
                    .filter(|s| !s.is_empty())
                    .map(String::from);
                let action_filter = query
                    .get("action")
                    .map(str::trim)
                    .filter(|s| !s.is_empty())
                    .map(String::from);
                let actions =
                    audit::recent(&db, 200, model_filter.as_deref(), action_filter.as_deref())
                        .await?;
                let identity = crate::auth::identity(req.ctx()).cloned();
                let csrf = ctx_csrf(req.ctx()).map(str::to_string);
                let html = crate::admin::layout::actions_render(
                    &db,
                    &registry,
                    &legacy_entries,
                    identity.as_ref(),
                    csrf.as_deref(),
                    &actions,
                    model_filter.as_deref(),
                    action_filter.as_deref(),
                )
                .await;
                Ok::<Response, Error>(with_admin_headers(crate::http::html(html)))
            }
        });

        // 0.7.1 Actionable Intelligence — suggestion → review → apply.
        // GET shows the proposed plan + review; POST (CSRF) commits
        // through the executor. No bypass of planner/review/executor.
        let sugg_get_entries = entries.clone();
        let sugg_get_db = db.clone();
        let sugg_get_registry = admin_new_registry.clone();
        router = router.get("/admin/suggestions/:admin/:field", move |req, params| {
            let legacy_entries = sugg_get_entries.clone();
            let db = sugg_get_db.clone();
            let registry = sugg_get_registry.clone();
            async move {
                if let Err(resp) = admin_guard(req.ctx()) {
                    return Ok(resp);
                }
                let admin_name = params.get("admin").unwrap_or("").to_string();
                let field = params.get("field").unwrap_or("").to_string();
                let identity = crate::auth::identity(req.ctx()).cloned();
                let csrf = ctx_csrf(req.ctx()).map(str::to_string);
                Ok::<Response, Error>(
                    suggestion_review_response(
                        &db,
                        &registry,
                        &legacy_entries,
                        identity.as_ref(),
                        csrf.as_deref(),
                        &admin_name,
                        &field,
                        None,
                    )
                    .await,
                )
            }
        });
        let sugg_post_entries = entries.clone();
        let sugg_post_db = db.clone();
        let sugg_post_registry = admin_new_registry.clone();
        router = router.post("/admin/suggestions/:admin/:field", move |req, params| {
            let legacy_entries = sugg_post_entries.clone();
            let db = sugg_post_db.clone();
            let registry = sugg_post_registry.clone();
            async move {
                if let Err(resp) = admin_guard(req.ctx()) {
                    return Ok(resp);
                }
                let admin_name = params.get("admin").unwrap_or("").to_string();
                let field = params.get("field").unwrap_or("").to_string();
                let (_, body, ctx) = req.into_parts();
                let form = read_form_from_parts(body).await?;
                require_csrf(&ctx, &form)?;
                let identity = crate::auth::identity(&ctx).cloned();
                let csrf = ctx_csrf(&ctx).map(str::to_string);
                Ok::<Response, Error>(
                    suggestion_apply_response(
                        &db,
                        &registry,
                        &legacy_entries,
                        identity.as_ref(),
                        csrf.as_deref(),
                        &admin_name,
                        &field,
                    )
                    .await,
                )
            }
        });

        // 0.7.2 — runtime schema reload. POST refreshes the cache,
        // returns to the dashboard. No restart, no recompile.
        router = router.post("/admin/schema/reload", move |req, _params| async move {
            if let Err(resp) = admin_guard(req.ctx()) {
                return Ok(resp);
            }
            let (_, body, ctx) = req.into_parts();
            let form = read_form_from_parts(body).await?;
            require_csrf(&ctx, &form)?;
            // Attempt the reload; on failure redirect with an error
            // flag in the query string. The dashboard renders a
            // banner for `?schema_reload=ok|err`.
            let redirect_url = match schema_cache::refresh() {
                Ok(_) => "/admin?schema_reload=ok",
                Err(_) => "/admin?schema_reload=err",
            };
            Ok::<Response, Error>(with_admin_headers(redirect(redirect_url)))
        });

        // /admin/:model is the canonical model path. Registered
        // *after* every literal /admin/<word> route above so the
        // router's first-match-wins lookup keeps reserved literals
        // (login, logout, profile, password_change, actions,
        // suggestions, schema, assets) bound to their dedicated
        // handlers. Anything else under /admin/<slug> resolves into
        // the template-based list page. Form submits go to the
        // dedicated /admin/:model/new and /admin/:model/:id/edit
        // routes mounted below — there is no catch-all POST.
        {
            let db = db.clone();
            let registry = admin_new_registry.clone();
            let model_entries = entries.clone();
            router =
                router.get("/admin/:model", move |req, params| {
                    let db = db.clone();
                    let registry = registry.clone();
                    let legacy_entries = model_entries.clone();
                    async move {
                        admin_model_index_get(&db, &registry, &legacy_entries, req, params).await
                    }
                });
        }

        // 0.10 stage 4f-a: GET /admin/:model/new and
        // /admin/:model/:id/edit route through the template-based
        // `form_render`. Registered BEFORE the `for registrar` loop
        // below so the generic routes shadow any legacy literals like
        // `/admin/patients/:id/edit` — unified template styling for
        // both registration surfaces.
        {
            let db = db.clone();
            let registry = admin_new_registry.clone();
            let form_new_entries = entries.clone();
            router = router.get("/admin/:model/new", move |req, params| {
                let db = db.clone();
                let registry = registry.clone();
                let legacy_entries = form_new_entries.clone();
                async move {
                    admin_model_form_get(&db, &registry, &legacy_entries, req, params, None).await
                }
            });
        }
        {
            let db = db.clone();
            let registry = admin_new_registry.clone();
            let form_edit_entries = entries.clone();
            router = router.get("/admin/:model/:id/edit", move |req, params| {
                let db = db.clone();
                let registry = registry.clone();
                let legacy_entries = form_edit_entries.clone();
                async move {
                    let id = params.get("id").map(str::to_string);
                    admin_model_form_get(
                        &db,
                        &registry,
                        &legacy_entries,
                        req,
                        params,
                        id.as_deref(),
                    )
                    .await
                }
            });
        }

        // Stage 4f-b: matching POST handlers.
        {
            let db = db.clone();
            let registry = admin_new_registry.clone();
            let create_entries = entries.clone();
            router = router.post("/admin/:model/new", move |req, params| {
                let db = db.clone();
                let registry = registry.clone();
                let legacy_entries = create_entries.clone();
                async move {
                    admin_model_create_post(&db, &registry, &legacy_entries, req, params).await
                }
            });
        }
        {
            let db = db.clone();
            let registry = admin_new_registry.clone();
            let update_entries = entries.clone();
            router = router.post("/admin/:model/:id/edit", move |req, params| {
                let db = db.clone();
                let registry = registry.clone();
                let legacy_entries = update_entries.clone();
                async move {
                    admin_model_update_post(&db, &registry, &legacy_entries, req, params).await
                }
            });
        }
        {
            let db = db.clone();
            let registry = admin_new_registry.clone();
            let delete_entries = entries.clone();
            router = router.post("/admin/:model/:id/delete", move |req, params| {
                let db = db.clone();
                let registry = registry.clone();
                let legacy_entries = delete_entries.clone();
                async move {
                    admin_model_delete_post(&db, &registry, &legacy_entries, req, params).await
                }
            });
        }
        // Phase 8 — POST /admin/:model/layout persists the chosen list
        // layout as the model's default in <model>.view.json. CSRF-protected,
        // edit-gated; mirrors the delete action's wiring. No `db` needed —
        // this writes a ViewSpec file, not the database.
        {
            let registry = admin_new_registry.clone();
            let layout_entries = entries.clone();
            router = router.post("/admin/:model/layout", move |req, params| {
                let registry = registry.clone();
                let legacy_entries = layout_entries.clone();
                async move { admin_model_layout_post(&registry, &legacy_entries, req, params).await }
            });
        }
        // Phase 9a — the composition editor: GET renders the field-role
        // editor; POST saves the edited ViewSpec. CSRF-protected, edit-gated.
        {
            let db = db.clone();
            let registry = admin_new_registry.clone();
            let view_get_entries = entries.clone();
            router =
                router.get("/admin/:model/view", move |req, params| {
                    let db = db.clone();
                    let registry = registry.clone();
                    let legacy_entries = view_get_entries.clone();
                    async move {
                        admin_model_view_get(&db, &registry, &legacy_entries, req, params).await
                    }
                });
        }
        {
            let db = db.clone();
            let registry = admin_new_registry.clone();
            let view_post_entries = entries.clone();
            router =
                router.post("/admin/:model/view", move |req, params| {
                    let db = db.clone();
                    let registry = registry.clone();
                    let legacy_entries = view_post_entries.clone();
                    async move {
                        admin_model_view_post(&db, &registry, &legacy_entries, req, params).await
                    }
                });
        }

        for registrar in self.registrars {
            router = registrar(router, db, entries.clone());
        }
        router
    }
}

impl Default for Admin {
    fn default() -> Self {
        Self::new()
    }
}

/// Convenience: mount CRUD routes and an `/admin` index for a single model.
pub fn register<T>(router: Router, db: &Db) -> Router
where
    T: AdminModel + Model,
{
    Admin::new().model::<T>().register(router, db)
}

fn mount_model<T>(mut router: Router, db: &Db, entries: Arc<Vec<AdminEntry>>) -> Router
where
    T: AdminModel + Model,
{
    let base = format!("/admin/{}", T::ADMIN_NAME);
    let create_path = format!("{base}/create");
    let edit_path = format!("{base}/:id/edit");
    let delete_path = format!("{base}/:id/delete");
    let history_path = format!("{base}/:id/history");
    let bulk_path = format!("{base}/bulk_action");

    // --- list (with search + filter via ?q=&status=&priority=) ---
    let list_db = db.clone();
    let list_entries = entries.clone();
    router = router.get(&base, move |req, _params| {
        let db = list_db.clone();
        let entries = list_entries.clone();
        async move {
            if let Err(resp) = admin_guard(req.ctx()) {
                return Ok(resp);
            }
            let query = req.query();
            let q = query
                .get("q")
                .map(str::trim)
                .filter(|s| !s.is_empty())
                .map(String::from);
            let status = query
                .get("status")
                .map(str::trim)
                .filter(|s| !s.is_empty())
                .map(String::from);
            let priority = query
                .get("priority")
                .map(str::trim)
                .filter(|s| !s.is_empty())
                .map(String::from);
            // Only accept sort values from the closed vocabulary —
            // anything else falls back to default so a crafted URL
            // can't surface a panic or reveal unknown ordering.
            let sort = query
                .get("sort")
                .map(str::trim)
                .filter(|s| !s.is_empty())
                .filter(|s| SORT_OPTIONS.iter().any(|(v, _)| *v == *s))
                .map(String::from);

            // Column visibility — rule-based default set computed
            // from the model's field shape via
            // [`default_list_columns`].
            let visible_columns: Vec<&'static str> = default_list_columns::<T>();

            let shell = Shell::from_ctx(&entries, Some(T::ADMIN_NAME), req.ctx());
            let all_items = T::all(&db).await?;
            let total = all_items.len();

            // Gather distinct filter-values from the unfiltered set so
            // the dropdown options reflect what actually exists in the
            // data, not a hard-coded list.
            let status_options = distinct_values::<T>(&all_items, "status");
            let priority_options = distinct_values::<T>(&all_items, "priority");

            // Relation-aware filters (Phase 5): one entry per FK
            // column on the model. Each either renders a dropdown
            // (target ≤ 500 rows AND declares display_field) or a
            // numeric fallback input with a clear hint.
            let registry = current_registry();
            let relation_filter_states = if registry.is_empty() {
                Vec::new()
            } else {
                build_relation_filters::<T>(&db, &registry, &query).await
            };

            // In-memory filter. Fine for the dev admin's typical row
            // counts; graduates to DB WHERE clauses when a project adds
            // an index or pagination layer.
            let mut filtered: Vec<&T> = all_items
                .iter()
                .filter(|item| {
                    if let Some(qs) = &q {
                        if !matches_query::<T>(item, qs) {
                            return false;
                        }
                    }
                    if let Some(s) = &status {
                        let v = item.field_display("status").unwrap_or_default();
                        if &v != s {
                            return false;
                        }
                    }
                    // Relation-aware equality filter: if the user
                    // asked for ?patient_id=7, drop rows whose FK
                    // value doesn't match. Applied before sort so the
                    // result count reflects the filtered set.
                    for rel in &relation_filter_states {
                        if let Some(wanted) = rel.current_value {
                            let actual = item
                                .field_display(&rel.field_name)
                                .and_then(|s| s.parse::<i64>().ok());
                            if actual != Some(wanted) {
                                return false;
                            }
                        }
                    }
                    if let Some(p) = &priority {
                        let v = item.field_display("priority").unwrap_or_default();
                        if &v != p {
                            return false;
                        }
                    }
                    true
                })
                .collect();

            // Sort. Default (when `sort` is absent) is newest-first —
            // matches the natural operator expectation of "most recent
            // at the top" for admin lists.
            match sort.as_deref() {
                Some("oldest") | Some("id_asc") => filtered.sort_by_key(|i| i.id()),
                Some("id_desc") => filtered.sort_by_key(|i| std::cmp::Reverse(i.id())),
                Some("newest") | None => filtered.sort_by_key(|i| std::cmp::Reverse(i.id())),
                _ => {}
            }

            let filters = ListFilters {
                q: q.as_deref(),
                status: status.as_deref(),
                status_options: &status_options,
                priority: priority.as_deref(),
                priority_options: &priority_options,
                sort: sort.as_deref(),
                relation_filters: &relation_filter_states,
                visible_columns: &visible_columns,
            };

            // Relation layer (0.9.0): FK label prefetch uses the same
            // registry we built above for filters. Missing schema
            // file or no declared relations → empty registry → zero
            // extra queries and the page renders exactly like
            // pre-0.9.0.
            let fk_labels = if registry.is_empty() {
                FkLabels::new()
            } else {
                fetch_fk_labels::<T>(&db, &filtered, &registry).await
            };
            let cell_ctx = CellCtx {
                registry: &registry,
                fk_labels: &fk_labels,
            };
            Ok::<Response, Error>(list_response::<T>(
                shell, &filtered, total, filters, &cell_ctx,
            ))
        }
    });

    // --- create (GET + POST) ---
    let create_entries = entries.clone();
    let create_form_db = db.clone();
    router = router.get(&create_path, move |req, _params| {
        let entries = create_entries.clone();
        let db = create_form_db.clone();
        async move {
            if let Err(resp) = admin_guard(req.ctx()) {
                return Ok(resp);
            }
            let shell = Shell::from_ctx(&entries, Some(T::ADMIN_NAME), req.ctx());
            // No item yet → relation ctx is empty; create form has
            // nothing to resolve and no inverse relations to count.
            let cell_ctx = CellCtx::empty();
            let inverse_counts = std::collections::HashMap::new();
            let registry = current_registry();
            let form_options = if registry.is_empty() {
                FormRelationOptions::new()
            } else {
                fetch_form_relation_options::<T>(&db, &registry).await
            };
            Ok::<Response, Error>(form_response::<T>(
                shell,
                FormMode::Create,
                &cell_ctx,
                &inverse_counts,
                &form_options,
            ))
        }
    });

    let create_db = db.clone();
    router = router.post(&create_path, move |req, _params| {
        let db = create_db.clone();
        async move {
            if let Err(resp) = admin_guard(req.ctx()) {
                return Ok(resp);
            }
            // Peer IP + user id must be captured before `req.into_parts()`
            // consumes the request.
            let peer_ip = req.peer_addr().map(|a| a.ip().to_string());
            let (_, body, ctx) = req.into_parts();
            let form = read_form_from_parts(body).await?;
            require_csrf(&ctx, &form)?;
            let user_id = ctx
                .get::<crate::auth::Identity>()
                .map(|i| i.user_id)
                .unwrap_or(0);

            let item = T::from_form(&form, None)?;
            let primary = primary_string_value::<T>(&item);
            let new_id = item.create(&db).await?;

            audit::record(
                &db,
                audit::LogEntry {
                    user_id,
                    action_type: audit::ActionType::Create,
                    model_name: T::ADMIN_NAME,
                    object_id: new_id,
                    ip_address: peer_ip.as_deref(),
                    summary: audit_summary(
                        audit::ActionType::Create,
                        T::singular_name(),
                        new_id,
                        &primary,
                    ),
                },
            )
            .await?;

            Ok::<Response, Error>(with_admin_headers(redirect(&format!(
                "/admin/{}",
                T::ADMIN_NAME
            ))))
        }
    });

    // --- edit (GET + POST) ---
    let edit_db = db.clone();
    let edit_entries = entries.clone();
    router = router.get(&edit_path, move |req, params| {
        let db = edit_db.clone();
        let entries = edit_entries.clone();
        async move {
            if let Err(resp) = admin_guard(req.ctx()) {
                return Ok(resp);
            }
            let id = parse_id_param(&params)?;
            let item = T::find(&db, id).await?.ok_or(Error::NotFound)?;
            let shell = Shell::from_ctx(&entries, Some(T::ADMIN_NAME), req.ctx());
            // Prefetch FK labels for this single row so the edit-
            // page "linked: <Name>" hint and any inverse-panel
            // counts (Phase 4) render without N+1 queries.
            let registry = current_registry();
            let items_ref: Vec<&T> = vec![&item];
            let fk_labels = if registry.is_empty() {
                FkLabels::new()
            } else {
                fetch_fk_labels::<T>(&db, &items_ref, &registry).await
            };
            let inverse_counts = if registry.is_empty() {
                std::collections::HashMap::new()
            } else {
                fetch_inverse_counts(&db, T::singular_name(), id, &registry).await
            };
            let cell_ctx = CellCtx {
                registry: &registry,
                fk_labels: &fk_labels,
            };
            let form_options = if registry.is_empty() {
                FormRelationOptions::new()
            } else {
                fetch_form_relation_options::<T>(&db, &registry).await
            };
            Ok::<Response, Error>(form_response::<T>(
                shell,
                FormMode::Edit { id, item: &item },
                &cell_ctx,
                &inverse_counts,
                &form_options,
            ))
        }
    });

    let update_db = db.clone();
    router = router.post(&edit_path, move |req, params| {
        let db = update_db.clone();
        async move {
            if let Err(resp) = admin_guard(req.ctx()) {
                return Ok(resp);
            }
            let id = parse_id_param(&params)?;
            let peer_ip = req.peer_addr().map(|a| a.ip().to_string());
            let (_, body, ctx) = req.into_parts();
            let form = read_form_from_parts(body).await?;
            require_csrf(&ctx, &form)?;
            let user_id = ctx
                .get::<crate::auth::Identity>()
                .map(|i| i.user_id)
                .unwrap_or(0);

            let item = T::from_form(&form, Some(id))?;
            let primary = primary_string_value::<T>(&item);
            item.update(&db).await?;

            audit::record(
                &db,
                audit::LogEntry {
                    user_id,
                    action_type: audit::ActionType::Update,
                    model_name: T::ADMIN_NAME,
                    object_id: id,
                    ip_address: peer_ip.as_deref(),
                    summary: audit_summary(
                        audit::ActionType::Update,
                        T::singular_name(),
                        id,
                        &primary,
                    ),
                },
            )
            .await?;

            Ok::<Response, Error>(with_admin_headers(redirect(&format!(
                "/admin/{}",
                T::ADMIN_NAME
            ))))
        }
    });

    // --- delete: GET = confirmation page, POST = perform delete ---
    let delete_confirm_db = db.clone();
    let delete_confirm_entries = entries.clone();
    router = router.get(&delete_path, move |req, params| {
        let db = delete_confirm_db.clone();
        let entries = delete_confirm_entries.clone();
        async move {
            if let Err(resp) = admin_guard(req.ctx()) {
                return Ok(resp);
            }
            let id = parse_id_param(&params)?;
            let item = T::find(&db, id).await?.ok_or(Error::NotFound)?;
            let shell = Shell::from_ctx(&entries, Some(T::ADMIN_NAME), req.ctx());
            Ok::<Response, Error>(delete_confirmation_response::<T>(shell, id, &item))
        }
    });

    let delete_db = db.clone();
    let delete_entries = entries.clone();
    router = router.post(&delete_path, move |req, params| {
        let db = delete_db.clone();
        let entries = delete_entries.clone();
        async move {
            if let Err(resp) = admin_guard(req.ctx()) {
                return Ok(resp);
            }
            let id = parse_id_param(&params)?;
            let peer_ip = req.peer_addr().map(|a| a.ip().to_string());
            let (_, body, ctx) = req.into_parts();
            let form = read_form_from_parts(body).await?;
            require_csrf(&ctx, &form)?;
            let user_id = ctx
                .get::<crate::auth::Identity>()
                .map(|i| i.user_id)
                .unwrap_or(0);

            // Fetch the record first so the audit summary can describe
            // what was deleted; the row is gone after `T::delete`.
            let primary = match T::find(&db, id).await? {
                Some(item) => primary_string_value::<T>(&item),
                None => String::new(),
            };

            // Phase 6 — delete guard. For every `has_many` inverse
            // pointing at this row, count blockers. If any exist,
            // refuse the delete and render a 409 page with a
            // per-blocker breakdown + links to filtered lists.
            let registry = current_registry();
            if !registry.is_empty() {
                let counts = fetch_inverse_counts(&db, T::singular_name(), id, &registry).await;
                let blockers: Vec<(&relations::InverseRelation, i64)> = registry
                    .has_many(T::singular_name())
                    .iter()
                    .filter_map(|inv| {
                        let key = format!("{}.{}", inv.source_model, inv.source_field);
                        counts
                            .get(&key)
                            .copied()
                            .filter(|n| *n > 0)
                            .map(|n| (inv, n))
                    })
                    .collect();
                if !blockers.is_empty() {
                    let shell = Shell::from_ctx(&entries, Some(T::ADMIN_NAME), &ctx);
                    return Ok::<Response, Error>(render_delete_blocked_page::<T>(
                        &shell, id, &primary, &blockers,
                    ));
                }
            }

            // Execute the delete. Defence in depth: SQLite's FK
            // enforcement still runs (a new reference could have
            // landed between the pre-check and this line); catch
            // that specific failure and render the same 409 page
            // instead of a generic 500.
            if let Err(e) = T::delete(&db, id).await {
                if is_foreign_key_violation(&e) {
                    let registry = current_registry();
                    let counts = fetch_inverse_counts(&db, T::singular_name(), id, &registry).await;
                    let blockers: Vec<(&relations::InverseRelation, i64)> = registry
                        .has_many(T::singular_name())
                        .iter()
                        .filter_map(|inv| {
                            let key = format!("{}.{}", inv.source_model, inv.source_field);
                            counts
                                .get(&key)
                                .copied()
                                .filter(|n| *n > 0)
                                .map(|n| (inv, n))
                        })
                        .collect();
                    let shell = Shell::from_ctx(&entries, Some(T::ADMIN_NAME), &ctx);
                    return Ok::<Response, Error>(render_delete_blocked_page::<T>(
                        &shell, id, &primary, &blockers,
                    ));
                }
                return Err(e);
            }

            audit::record(
                &db,
                audit::LogEntry {
                    user_id,
                    action_type: audit::ActionType::Delete,
                    model_name: T::ADMIN_NAME,
                    object_id: id,
                    ip_address: peer_ip.as_deref(),
                    summary: audit_summary(
                        audit::ActionType::Delete,
                        T::singular_name(),
                        id,
                        &primary,
                    ),
                },
            )
            .await?;

            Ok::<Response, Error>(with_admin_headers(redirect(&format!(
                "/admin/{}",
                T::ADMIN_NAME
            ))))
        }
    });

    // --- per-object history (Django parity). Reads from
    // `rustio_admin_actions` so every add / change / delete that went
    // through the admin is visible, newest first.
    let history_db = db.clone();
    let history_entries = entries.clone();
    router = router.get(&history_path, move |req, params| {
        let db = history_db.clone();
        let entries = history_entries.clone();
        async move {
            if let Err(resp) = admin_guard(req.ctx()) {
                return Ok(resp);
            }
            let id = parse_id_param(&params)?;
            let item = T::find(&db, id).await?.ok_or(Error::NotFound)?;
            let actions = audit::for_object(&db, T::ADMIN_NAME, id).await?;
            let shell = Shell::from_ctx(&entries, Some(T::ADMIN_NAME), req.ctx());
            Ok::<Response, Error>(object_history_response::<T>(shell, id, &item, &actions))
        }
    });

    // --- bulk actions (Django parity). POST with `_selected` + `action`.
    // First POST → render a confirmation page listing the records that
    // will be touched. Second POST (with `_confirm=yes`) → perform it.
    // Individual audit entries are written per record so per-object
    // history stays complete even for bulk operations.
    let bulk_db = db.clone();
    let bulk_entries = entries.clone();
    router = router.post(&bulk_path, move |req, _params| {
        let db = bulk_db.clone();
        let entries = bulk_entries.clone();
        async move {
            if let Err(resp) = admin_guard(req.ctx()) {
                return Ok(resp);
            }
            let peer_ip = req.peer_addr().map(|a| a.ip().to_string());
            let (_, body, ctx) = req.into_parts();
            let form = read_form_from_parts(body).await?;
            require_csrf(&ctx, &form)?;
            let user_id = ctx
                .get::<crate::auth::Identity>()
                .map(|i| i.user_id)
                .unwrap_or(0);

            let action = form.get("action").unwrap_or("").trim().to_string();
            let selected_raw = form.get("_selected").unwrap_or("").to_string();
            let ids: Vec<i64> = selected_raw
                .split(',')
                .map(str::trim)
                .filter(|s| !s.is_empty())
                .filter_map(|s| s.parse::<i64>().ok())
                .collect();
            let confirmed = form.get("_confirm").map(|v| v == "yes").unwrap_or(false);

            if ids.is_empty() || action.is_empty() {
                return Ok::<Response, Error>(with_admin_headers(redirect(&format!(
                    "/admin/{}",
                    T::ADMIN_NAME
                ))));
            }

            if action != "delete" {
                return Err(Error::BadRequest(
                    format!("Unknown bulk action `{action}`",),
                ));
            }

            // First POST (no `_confirm=yes`): render the intermediate
            // confirmation page. User reviews the items and posts again.
            if !confirmed {
                let mut items: Vec<(i64, String)> = Vec::with_capacity(ids.len());
                for id in &ids {
                    if let Some(item) = T::find(&db, *id).await? {
                        let primary = primary_string_value::<T>(&item);
                        items.push((*id, primary));
                    }
                }
                let shell = Shell::from_ctx(&entries, Some(T::ADMIN_NAME), &ctx);
                return Ok::<Response, Error>(bulk_delete_confirmation_response::<T>(
                    &shell, &items,
                ));
            }

            // Confirmed: delete each record, record an audit entry per
            // row so object history remains per-record complete.
            for id in &ids {
                let primary = match T::find(&db, *id).await? {
                    Some(item) => primary_string_value::<T>(&item),
                    None => continue, // already gone; skip silently
                };
                T::delete(&db, *id).await?;

                let mut summary =
                    audit_summary(audit::ActionType::Delete, T::singular_name(), *id, &primary);
                summary.push_str(" (via bulk action)");

                audit::record(
                    &db,
                    audit::LogEntry {
                        user_id,
                        action_type: audit::ActionType::Delete,
                        model_name: T::ADMIN_NAME,
                        object_id: *id,
                        ip_address: peer_ip.as_deref(),
                        summary,
                    },
                )
                .await?;
            }

            Ok::<Response, Error>(with_admin_headers(redirect(&format!(
                "/admin/{}",
                T::ADMIN_NAME
            ))))
        }
    });

    router
}

fn parse_id_param(params: &crate::router::Params) -> Result<i64, Error> {
    params
        .get("id")
        .and_then(|s| s.parse::<i64>().ok())
        .ok_or_else(|| Error::BadRequest(String::from("invalid id")))
}

/// Best-effort display string for an item's primary identifier, used in
/// audit summaries. Returns the first editable `String` field's value,
/// or an empty string when none is available.
fn primary_string_value<T: AdminModel>(item: &T) -> String {
    T::FIELDS
        .iter()
        .find(|f| f.editable && matches!(f.ty, FieldType::String))
        .and_then(|f| item.field_display(f.name))
        .filter(|s| !s.is_empty())
        .unwrap_or_default()
}

/// Compose a human-readable audit line, e.g.
/// `Created Task #5: Ship 0.4.0` or `Deleted User #12`.
fn audit_summary(action: audit::ActionType, singular: &str, id: i64, primary: &str) -> String {
    let verb = action.label();
    if primary.is_empty() {
        format!("{verb} {singular} #{id}")
    } else {
        format!("{verb} {singular} #{id}: {primary}")
    }
}

// ---------------------------------------------------------------------------
// Constants + context helpers
// ---------------------------------------------------------------------------

/// Maximum size of an admin form body.
pub const MAX_FORM_BODY_BYTES: usize = crate::http::MAX_REQUEST_BODY_BYTES;

/// Name of the hidden form field that carries the per-session CSRF token.
pub const CSRF_FIELD: &str = "_csrf";

fn ctx_csrf(ctx: &crate::context::Context) -> Option<&str> {
    ctx.get::<crate::auth::CsrfToken>().map(|t| t.0.as_str())
}

fn ctx_user_email(ctx: &crate::context::Context) -> Option<&str> {
    ctx.get::<crate::auth::Identity>().map(|i| i.email.as_str())
}

fn csrf_input(csrf: Option<&str>) -> String {
    match csrf {
        Some(token) if !token.is_empty() => format!(
            r#"<input type="hidden" name="{name}" value="{value}">"#,
            name = CSRF_FIELD,
            value = escape_html(token),
        ),
        _ => String::new(),
    }
}

fn require_csrf(ctx: &crate::context::Context, form: &FormData) -> Result<(), Error> {
    let expected = ctx
        .get::<crate::auth::CsrfToken>()
        .map(|t| t.0.as_str())
        .unwrap_or("");
    let provided = form.get(CSRF_FIELD).unwrap_or("");
    if !crate::auth::csrf::verify_token(expected, provided) {
        return Err(Error::Forbidden);
    }
    Ok(())
}

fn with_admin_headers(mut resp: Response) -> Response {
    use hyper::header::HeaderValue;
    let h = resp.headers_mut();
    h.insert("x-frame-options", HeaderValue::from_static("DENY"));
    h.insert(
        "x-content-type-options",
        HeaderValue::from_static("nosniff"),
    );
    h.insert("referrer-policy", HeaderValue::from_static("no-referrer"));
    if crate::auth::in_production() {
        h.insert(
            "strict-transport-security",
            HeaderValue::from_static("max-age=31536000; includeSubDomains"),
        );
    }
    resp
}

async fn read_form(req: Request) -> Result<FormData, Error> {
    let (_, body, _) = req.into_parts();
    read_form_from_parts(body).await
}

async fn read_form_from_parts(body: hyper::body::Incoming) -> Result<FormData, Error> {
    let limited = http_body_util::Limited::new(body, MAX_FORM_BODY_BYTES);
    let collected = limited.collect().await.map_err(|e| {
        if e.downcast_ref::<http_body_util::LengthLimitError>()
            .is_some()
        {
            Error::PayloadTooLarge
        } else {
            Error::BadRequest(e.to_string())
        }
    })?;
    let bytes = collected.to_bytes();
    let body_str = std::str::from_utf8(&bytes).map_err(|e| Error::BadRequest(e.to_string()))?;
    Ok(FormData::parse(body_str))
}

fn redirect(to: &str) -> Response {
    hyper::Response::builder()
        .status(303)
        .header("location", to)
        .body(Full::new(Bytes::new()))
        .expect("valid redirect")
}

/// Serve the bundled admin stylesheet.
///
/// We use `no-cache, must-revalidate` rather than a long-lived
/// `max-age` because the CSS is baked into the binary via
/// `include_str!` — when a project redeploys, the CSS may have
/// changed, and a stale browser cache would silently render the old
/// UI for up to the cache lifetime. `no-cache` forces the browser to
/// re-send the request every time, but the 304 short-circuit on the
/// cheap ETag keeps the wire cost near-zero for repeat loads.
///
/// The ETag fingerprints the compiled CSS bytes so it changes every
/// time the binary is rebuilt with a different stylesheet. Browsers
/// sending `If-None-Match` get 304 Not Modified.
fn admin_css_response() -> Response {
    use hyper::header::HeaderValue;
    let body = ADMIN_CSS_BUNDLE.as_bytes();
    // Cheap stable fingerprint: length + first/last 4 bytes. Good
    // enough to change whenever the CSS content changes; avoids
    // pulling a hash crate. `'W/'` prefix marks it as a weak ETag
    // (byte-for-byte equivalence not guaranteed across CDNs).
    let etag = {
        let len = body.len();
        let head = u32::from_le_bytes([
            *body.first().unwrap_or(&0),
            *body.get(1).unwrap_or(&0),
            *body.get(2).unwrap_or(&0),
            *body.get(3).unwrap_or(&0),
        ]);
        let tail = u32::from_le_bytes([
            *body.get(len.saturating_sub(4)).unwrap_or(&0),
            *body.get(len.saturating_sub(3)).unwrap_or(&0),
            *body.get(len.saturating_sub(2)).unwrap_or(&0),
            *body.get(len.saturating_sub(1)).unwrap_or(&0),
        ]);
        format!("W/\"rio-{len}-{head:x}-{tail:x}\"")
    };
    let mut resp = hyper::Response::builder()
        .status(200)
        .header("content-type", "text/css; charset=utf-8")
        .header("cache-control", "no-cache, must-revalidate")
        .header("etag", etag)
        .body(Full::new(Bytes::from_static(ADMIN_CSS_BUNDLE.as_bytes())))
        .expect("valid css response");
    let h = resp.headers_mut();
    // Nosniff on the stylesheet too — an attacker who can upload to an
    // admin-adjacent endpoint mustn't get the browser to execute it.
    h.insert(
        "x-content-type-options",
        HeaderValue::from_static("nosniff"),
    );
    resp
}

/// Serve the admin favicon — a scalable SVG. Cached for a day because
/// the brand mark changes rarely (and only with a redeploy), and the
/// bytes are tiny. `nosniff` for the same reason the CSS has it: an
/// attacker must not trick the browser into executing it as script.
/// `<span class="rio-env-chip">` markup, rendered consistently
/// everywhere the admin shell appears (main pages *and* the auth
/// shell). Signed-out operators still see whether they're logging
/// into dev or prod, which closes a small phishing surface — an
/// attacker who puts up a lookalike dev admin can't hide the chip.
fn env_chip_html() -> String {
    if crate::auth::in_production() {
        r#"<span class="rio-env-chip is-prod">production</span>"#.to_string()
    } else {
        r#"<span class="rio-env-chip">development</span>"#.to_string()
    }
}

/// Generic static-asset response for the 0.10+ `/admin/static/…` bundle.
/// The bytes are pinned to the compiled binary, so a long-ish cache is
/// safe — when the binary redeploys, the content-length changes and
/// the etag changes with it. `nosniff` for the same reason every other
/// admin asset has it.
fn bundled_asset_response(bytes: &'static [u8], content_type: &'static str) -> Response {
    use hyper::header::HeaderValue;
    let etag = {
        let len = bytes.len();
        let head = u32::from_le_bytes([
            *bytes.first().unwrap_or(&0),
            *bytes.get(1).unwrap_or(&0),
            *bytes.get(2).unwrap_or(&0),
            *bytes.get(3).unwrap_or(&0),
        ]);
        let tail = u32::from_le_bytes([
            *bytes.get(len.saturating_sub(4)).unwrap_or(&0),
            *bytes.get(len.saturating_sub(3)).unwrap_or(&0),
            *bytes.get(len.saturating_sub(2)).unwrap_or(&0),
            *bytes.get(len.saturating_sub(1)).unwrap_or(&0),
        ]);
        format!("W/\"rio-{len}-{head:x}-{tail:x}\"")
    };
    let mut resp = hyper::Response::builder()
        .status(200)
        .header("content-type", content_type)
        .header("cache-control", "public, max-age=3600")
        .header("etag", etag)
        .body(Full::new(Bytes::from_static(bytes)))
        .expect("valid static asset response");
    resp.headers_mut().insert(
        "x-content-type-options",
        HeaderValue::from_static("nosniff"),
    );
    resp
}

fn admin_favicon_response() -> Response {
    use hyper::header::HeaderValue;
    let mut resp = hyper::Response::builder()
        .status(200)
        .header("content-type", "image/svg+xml")
        .header("cache-control", "public, max-age=86400")
        .body(Full::new(Bytes::from_static(ADMIN_FAVICON_SVG.as_bytes())))
        .expect("valid favicon response");
    resp.headers_mut().insert(
        "x-content-type-options",
        HeaderValue::from_static("nosniff"),
    );
    resp
}

// ---------------------------------------------------------------------------
// Shell (sidebar + topbar) — wraps every authenticated page
// ---------------------------------------------------------------------------

/// Per-request data the shell needs: registered models (for the sidebar),
/// which one is active (for highlight), the signed-in user email (for
/// the sidebar footer), and the session's CSRF token (for the logout
/// form). Cheaply constructed from a request context.
struct Shell<'a> {
    entries: &'a [AdminEntry],
    active: Option<&'a str>,
    user_email: Option<&'a str>,
    csrf: Option<&'a str>,
}

impl<'a> Shell<'a> {
    fn from_ctx(
        entries: &'a [AdminEntry],
        active: Option<&'a str>,
        ctx: &'a crate::context::Context,
    ) -> Self {
        Self {
            entries,
            active,
            user_email: ctx_user_email(ctx),
            csrf: ctx_csrf(ctx),
        }
    }
}

/// One breadcrumb segment: `(label, optional href)`. The last segment
/// is rendered as the current page (no link).
type Crumb<'a> = (&'a str, Option<&'a str>);

fn render_breadcrumbs(crumbs: &[Crumb<'_>]) -> String {
    if crumbs.is_empty() {
        return String::new();
    }
    let sep = format!(
        r#"<span class="rio-crumb-sep">{}</span>"#,
        icon_chevron_right()
    );
    let mut out = String::from(r#"<nav class="rio-breadcrumbs" aria-label="Breadcrumb">"#);
    for (i, (label, href)) in crumbs.iter().enumerate() {
        let is_last = i == crumbs.len() - 1;
        if i > 0 {
            out.push_str(&sep);
        }
        match (is_last, href) {
            (true, _) => {
                out.push_str(&format!(
                    r#"<span class="rio-crumb-current" aria-current="page">{}</span>"#,
                    escape_html(label),
                ));
            }
            (false, Some(h)) => {
                out.push_str(&format!(
                    r#"<a href="{}">{}</a>"#,
                    escape_html(h),
                    escape_html(label),
                ));
            }
            (false, None) => {
                out.push_str(&escape_html(label));
            }
        }
    }
    out.push_str("</nav>");
    out
}

/// Sentinel passed to `Shell::active` for the built-in "Recent
/// actions" page. Prefixed with `__` so it cannot collide with any
/// user model's `admin_name` (which is lowercased, alphanumeric).
const NAV_ACTIONS: &str = "__actions";

/// Humanise a macro-generated `DISPLAY_NAME` for sidebar/dashboard
/// display. The macro outputs Rust's camel/pascal plural (e.g.
/// `VitalSigns`, `AppointmentEvents`, `Staffs`, `CheckIns`) which
/// reads awkwardly as a nav label. This helper:
///
///   * inserts a space before every internal uppercase letter, so
///     `VitalSigns` → `Vital Signs`, `AppointmentEvents` → `Appointment Events`,
///     `MedicalRecords` → `Medical Records`, `CheckIns` → `Check Ins`;
///   * fixes the two English pluralisations the macro gets wrong:
///     `Staffs` → `Staff` (already a mass noun), `Diagnosis` →
///     `Diagnoses`.
///
/// Returns `String` because some transformations (the two special
/// cases) substitute; we avoid returning `Cow<str>` to keep the
/// call site mono-morphic.
fn humanise_model_label(name: &str) -> String {
    // Two hard-coded fixes first — English plural edge-cases the
    // macro cannot infer.
    if name == "Staffs" {
        return "Staff".to_string();
    }
    if name == "Diagnosis" {
        return "Diagnoses".to_string();
    }
    // Insert a space before each internal uppercase letter.
    let mut out = String::with_capacity(name.len() + 4);
    for (i, ch) in name.chars().enumerate() {
        if i > 0 && ch.is_ascii_uppercase() {
            out.push(' ');
        }
        out.push(ch);
    }
    out
}

fn render_sidebar(shell: &Shell<'_>) -> String {
    let design = design::Design::global();
    let user_facing: Vec<&AdminEntry> = shell.entries.iter().filter(|e| !e.core).collect();

    let mut models_html = String::new();
    if !user_facing.is_empty() {
        models_html.push_str(r#"<div class="rio-nav">"#);
        models_html.push_str(r#"<div class="rio-nav-section">Models</div>"#);
        for e in &user_facing {
            let active_cls = if shell.active == Some(e.admin_name) {
                "rio-nav-link is-active"
            } else {
                "rio-nav-link"
            };
            models_html.push_str(&format!(
                r#"<a class="{cls}" href="/admin/{name}">{icon}<span>{label}</span></a>"#,
                cls = active_cls,
                name = escape_html(e.admin_name),
                icon = icon_layers(),
                label = escape_html(&humanise_model_label(e.display_name)),
            ));
        }
        models_html.push_str("</div>");
    }

    // Dashboard is active by default (no model page, no built-in
    // sentinel). Recent-actions and the other built-ins set explicit
    // sentinel strings so they can claim their own highlight without
    // this falling through and lighting up Dashboard on their pages.
    let dashboard_active = if shell.active.is_none() {
        "rio-nav-link is-active"
    } else {
        "rio-nav-link"
    };
    let actions_active = if shell.active == Some(NAV_ACTIONS) {
        "rio-nav-link is-active"
    } else {
        "rio-nav-link"
    };

    let logout_form = if shell.csrf.is_some() {
        format!(
            r#"<form class="rio-sidebar-logout" method="post" action="/admin/logout">
{csrf}
<button type="submit">{icon}<span>Sign out</span></button>
</form>"#,
            csrf = csrf_input(shell.csrf),
            icon = icon_logout(),
        )
    } else {
        String::new()
    };

    let email = shell.user_email.unwrap_or("");
    let avatar_initial = email
        .chars()
        .next()
        .map(|c| c.to_ascii_uppercase().to_string())
        .unwrap_or_else(|| String::from("·"));

    let user_block = if shell.user_email.is_some() {
        // The user chip is clickable → /admin/profile. Matches
        // Django's "Welcome, name" dropdown in the header, but fits
        // our sidebar footer.
        format!(
            r#"<a class="rio-sidebar-user" href="/admin/profile" title="Your profile">
<span class="rio-avatar">{avatar}</span>
<span class="rio-user-email">{email}</span>
</a>"#,
            avatar = escape_html(&avatar_initial),
            email = escape_html(email),
        )
    } else {
        String::new()
    };

    format!(
        r#"<aside class="rio-sidebar">
<div class="rio-sidebar-inner">
<a class="rio-brand" href="/admin">
<span class="rio-brand-mark">{logo}</span>
<span class="rio-brand-meta">
<span class="rio-brand-name">{project}</span>
<span class="rio-brand-label">Admin</span>
</span>
</a>
<nav class="rio-nav">
<a class="{dash}" href="/admin">{dash_icon}<span>Dashboard</span></a>
<a class="{actions}" href="/admin/actions">{actions_icon}<span>Recent actions</span></a>
</nav>
{models}
<div class="rio-sidebar-footer">
{user}
{logout}
</div>
</div>
</aside>"#,
        logo = escape_html(&design.logo_initial),
        project = escape_html(&design.project_name),
        dash = dashboard_active,
        dash_icon = icon_dashboard(),
        actions = actions_active,
        actions_icon = icon_activity(),
        models = models_html,
        user = user_block,
        logout = logout_form,
    )
}

/// Render an authenticated shell page. Used for dashboard, list, form,
/// and delete-confirmation responses.
#[allow(clippy::too_many_arguments)]
fn render_shell_page(
    shell: &Shell<'_>,
    status: u16,
    document_title: &str,
    page_title: &str,
    page_subtitle: Option<&str>,
    breadcrumbs: &[Crumb<'_>],
    actions: &str,
    body: &str,
) -> Response {
    let design = design::Design::global();

    let sidebar = render_sidebar(shell);
    let crumbs = render_breadcrumbs(breadcrumbs);

    let env_chip = env_chip_html();

    // Topbar action cluster: env-chip + Home + Notifications bell +
    // Messages + Logout button with a visible "Logout" label.
    // Rendered only when we have an identity (i.e. a CSRF token to
    // back the logout form). On unauthenticated error pages the
    // cluster collapses to just the env-chip.
    let topbar_actions = match shell.csrf {
        Some(csrf) => format!(
            r#"<div class="rio-topbar-actions">
{env}
<a class="rio-topbar-icon" href="/admin" title="Home" aria-label="Home">{home}</a>
<button class="rio-topbar-icon" type="button" title="Notifications" aria-label="Notifications">{bell}<span class="rio-topbar-dot"></span></button>
<button class="rio-topbar-icon" type="button" title="Messages" aria-label="Messages">{mail}</button>
<form class="rio-topbar-logout" method="post" action="/admin/logout">
<input type="hidden" name="_csrf" value="{csrf_val}">
<button type="submit" title="Sign out">{logout}<span>Logout</span></button>
</form>
</div>"#,
            env = env_chip,
            home = icon_home(),
            bell = icon_bell(),
            mail = icon_mail(),
            logout = icon_logout(),
            csrf_val = escape_html(csrf),
        ),
        None => format!(
            r#"<div class="rio-topbar-actions">{env}</div>"#,
            env = env_chip
        ),
    };

    let subtitle_html = page_subtitle
        .map(|s| format!(r#"<p class="rio-page-subtitle">{}</p>"#, escape_html(s)))
        .unwrap_or_default();

    let actions_block = if actions.is_empty() {
        String::new()
    } else {
        format!(r#"<div class="rio-page-actions">{actions}</div>"#)
    };

    let theme_style = format!(
        "\n:root {{\n  --rio-primary: {p};\n  --rio-primary-hover: {ph};\n  --rio-accent: {a};\n  --rio-accent-hover: {ah};\n}}\n",
        p = escape_css_color(&design.primary_color),
        ph = escape_css_color(&design.primary_color),
        a = escape_css_color(&design.accent_color),
        ah = escape_css_color(&design.accent_color),
    );

    let density_class = match design.density {
        design::Density::Comfortable => "",
        design::Density::Compact => " rio-density-compact",
    };

    let body_html = format!(
        r#"<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{doc_title} · {project}</title>
<link rel="stylesheet" href="/admin/assets/admin.css?v={css_ver}">
<link rel="icon" type="image/svg+xml" href="/admin/assets/favicon.svg">
<style>{theme}</style>
</head>
<body class="rio-body{density}">
<div class="rio-app">
{sidebar}
<main class="rio-main">
<div class="rio-container">
<header class="rio-topbar">
{crumbs}
{topbar_actions}
</header>
<div class="rio-page-header">
<div>
<h1 class="rio-page-title">{page_title}</h1>
{subtitle}
</div>
{actions}
</div>
{body}
</div>
</main>
</div>
<script>
// Admin Intelligence Layer (0.7.0) — minimal JS for PII toggle.
// Click a .rio-pii-toggle to reveal / hide the adjacent masked value.
document.addEventListener("click", function(e){{
  var btn = e.target.closest ? e.target.closest(".rio-pii-toggle") : null;
  if(!btn) return;
  // The masked <span> is the button's previous sibling by construction.
  var span = btn.previousElementSibling;
  if(!span || !span.classList.contains("rio-pii")) return;
  if(span.getAttribute("data-hidden") === "1"){{
    span.textContent = span.getAttribute("data-value") || "";
    span.setAttribute("data-hidden","0");
    btn.textContent = "hide";
  }} else {{
    span.textContent = span.getAttribute("data-mask") || "";
    span.setAttribute("data-hidden","1");
    btn.textContent = "show";
  }}
}});
</script>
</body>
</html>"#,
        doc_title = escape_html(document_title),
        project = escape_html(&design.project_name),
        theme = theme_style,
        density = density_class,
        sidebar = sidebar,
        crumbs = crumbs,
        topbar_actions = topbar_actions,
        page_title = escape_html(page_title),
        subtitle = subtitle_html,
        actions = actions_block,
        body = body,
        css_ver = ADMIN_CSS_VER,
    );

    let resp = hyper::Response::builder()
        .status(status)
        .header("content-type", "text/html; charset=utf-8")
        // Kill all HTML caching so the browser always fetches a fresh
        // admin page and never paints a stale shell. The CSS bundle
        // has its own `?v=<len>` cache-buster; these headers close
        // the remaining gap on the HTML itself.
        .header(
            "cache-control",
            "no-store, no-cache, must-revalidate, max-age=0",
        )
        .header("pragma", "no-cache")
        .header("expires", "0")
        .body(Full::new(Bytes::from(body_html)))
        .expect("valid response");
    with_admin_headers(resp)
}

/// Minimal sanitiser for CSS colour tokens emitted inline in a
/// `<style>` block. We reject any input containing `;`, `{`, `}`, `<`,
/// or backslash to prevent a breakout from the CSS context into another
/// attribute or the HTML parser. Returns the original string when safe,
/// or a fallback token when suspicious.
fn escape_css_color(s: &str) -> &str {
    if s.contains([';', '{', '}', '<', '\\']) {
        // Fall back to the default primary colour.
        "#0f172a"
    } else {
        s
    }
}

// ---------------------------------------------------------------------------
// Dashboard (admin index)
// ---------------------------------------------------------------------------

/// Register a config-driven model under its own slug. The closure
/// captures `cfg` and clones it on every lookup, so the registry's
/// `Fn` factory can build a fresh `Box<dyn AdminUiModel>` per
/// request without any global state.
pub fn register_generated(
    registry: &mut crate::admin::admin_form_bridge::AdminRegistry,
    cfg: crate::admin::admin_generator::AdminModelConfig,
) {
    let slug = cfg.slug;
    registry.register(slug, move || {
        crate::admin::admin_generator::from_config(cfg.clone())
    });
}

/// Schema-driven counterpart to [`register_generated`]. Reads the
/// table's columns via `PRAGMA table_info`, builds an
/// [`AdminModelConfig`](crate::admin::admin_generator::AdminModelConfig)
/// from them, and registers it under the derived slug. The table
/// must already exist — this helper does **not** issue
/// `CREATE TABLE`.
pub async fn register_from_table(
    db: &Db,
    registry: &mut crate::admin::admin_form_bridge::AdminRegistry,
    table: &str,
) -> Result<(), Error> {
    let cfg = crate::admin::schema_introspect::generate_from_table(db, table).await?;
    register_generated(registry, cfg);
    Ok(())
}

/// Context-aware hint shown on an empty list page. Combines the
/// country (e.g. "In Sweden…") with the active industry conventions
/// (e.g. "…usually include personnummer and income"). Returns `None`
/// when the project has no context or the current model doesn't
/// intersect any known convention — better to stay silent than
/// generic.
fn empty_state_hint<T: AdminModel>(context: Option<&crate::ai::ContextConfig>) -> Option<String> {
    let ctx = context?;
    let schema = ctx.industry_schema()?;
    // Only emit the hint when the current model actually overlaps the
    // industry's required fields — a hint about personnummer on a
    // `Widget` model is noise.
    let model_has_convention = schema
        .required_fields
        .iter()
        .any(|f| T::FIELDS.iter().any(|af| af.name == f.as_str()));
    if !model_has_convention {
        return None;
    }
    let country_phrase = match ctx.country.as_deref() {
        Some(cc) if cc.eq_ignore_ascii_case("SE") => "In Sweden, ",
        Some(cc) if cc.eq_ignore_ascii_case("NO") => "In Norway, ",
        _ => "",
    };
    let industry = ctx.industry.as_deref().unwrap_or("");
    let singular_lower = T::singular_name().to_lowercase();
    let fields_list = schema.required_fields.join(", ");
    Some(format!(
        "{country}{industry} {singular}s usually include {fields}.",
        country = country_phrase,
        industry = industry,
        singular = singular_lower,
        fields = fields_list,
    ))
}

// ---------------------------------------------------------------------------
// List page
// ---------------------------------------------------------------------------

/// All filter state for a list page in one bundle — lets the handler
/// pass params cleanly and lets the renderer reflect them back in the
/// form (so the search box keeps its value after submission).
struct ListFilters<'a> {
    q: Option<&'a str>,
    status: Option<&'a str>,
    status_options: &'a [String],
    priority: Option<&'a str>,
    priority_options: &'a [String],
    /// Current sort mode (`newest` | `oldest` | `id_asc` | `id_desc`).
    /// `None` → default (newest first).
    sort: Option<&'a str>,
    /// Phase 5 — one entry per `belongs_to` relation owned by the
    /// model, carrying either a dropdown option list or a signal to
    /// render a numeric fallback input.
    relation_filters: &'a [RelationFilterState],
    /// Column-visibility set used by [`list_response`] to filter
    /// `T::FIELDS` when rendering the `<thead>` and row cells. Fed
    /// from [`default_list_columns`].
    visible_columns: &'a [&'static str],
}

/// Phase 5 — how one relation-aware filter should render. Assembled
/// by the list handler per request and consumed by the toolbar.
struct RelationFilterState {
    /// FK column name on the source model (e.g. `"patient_id"`).
    field_name: String,
    /// Human-readable label shown above the control (e.g. `"Patient"`).
    label: String,
    /// Currently-selected FK value pulled from the query string.
    current_value: Option<i64>,
    /// Rendering mode — determined by the row count of the target.
    mode: RelationFilterMode,
}

enum RelationFilterMode {
    /// Target has at most [`relations::RELATION_FILTER_DROPDOWN_CAP`]
    /// rows AND declares a `display_field`. The dropdown lists
    /// `(id, display)` pairs.
    Dropdown { options: Vec<(i64, String)> },
    /// Either too many rows or no `display_field` declared — the
    /// admin renders a numeric input instead. `too_many` toggles the
    /// hint copy so an operator knows *why* they got the fallback.
    Numeric { too_many: bool },
}

impl ListFilters<'_> {
    fn is_active(&self) -> bool {
        self.q.is_some()
            || self.status.is_some()
            || self.priority.is_some()
            || self.sort.is_some()
            || self
                .relation_filters
                .iter()
                .any(|r| r.current_value.is_some())
    }
}

/// The fixed sort vocabulary the toolbar exposes. Kept as
/// `(value, label)` tuples so the renderer can build a `<select>`
/// with the correct `<option selected>` mark from this single source.
const SORT_OPTIONS: &[(&str, &str)] = &[
    ("newest", "Newest first"),
    ("oldest", "Oldest first"),
    ("id_asc", "ID ↑"),
    ("id_desc", "ID ↓"),
];

// ---------------------------------------------------------------------------
// Relation resolution helpers
// ---------------------------------------------------------------------------

/// Map keyed by FK field name → (referenced id → display label).
/// Built once per list/detail render by [`fetch_fk_labels`]. An empty
/// outer map, or a missing inner entry, is the "fall back to #<id>"
/// signal to the renderer — no display_field was declared, or the
/// target row has been deleted, or the prefetch query failed. The
/// renderer never panics on a missing lookup.
type FkLabels = std::collections::HashMap<String, std::collections::HashMap<i64, String>>;

/// Per-form dropdown option sets: FK field name → ordered list of
/// `(id, label)` pairs fetched from the target table. Populated by
/// [`fetch_form_relation_options`] and consumed by [`render_field`].
///
/// A field is present in the map only when:
///   * the field carries `#[rustio(belongs_to = "…")]`,
///   * the target declares a `display_field`,
///   * the target has `<= RELATION_FILTER_DROPDOWN_CAP` rows.
///
/// Absence from the map means the form renderer falls back to a raw
/// `<input type="number">` — same UX as the list-page filter's
/// `Numeric { too_many }` mode.
type FormRelationOptions = std::collections::HashMap<String, Vec<(i64, String)>>;

/// Bundle passed into [`render_cell`] so it can resolve foreign-key
/// columns without further DB work. Construction sites own the
/// registry and the prefetched labels.
struct CellCtx<'a> {
    registry: &'a relations::RelationRegistry,
    fk_labels: &'a FkLabels,
}

impl CellCtx<'_> {
    /// An empty context — registry with no relations, no labels.
    /// Used by tests and by call sites that haven't yet plumbed the
    /// registry through. Renders behave exactly like the pre-0.9.0
    /// admin (every FK column is a raw number).
    fn empty() -> CellCtx<'static> {
        static EMPTY_REG: std::sync::OnceLock<relations::RelationRegistry> =
            std::sync::OnceLock::new();
        static EMPTY_LABELS: std::sync::OnceLock<FkLabels> = std::sync::OnceLock::new();
        CellCtx {
            registry: EMPTY_REG.get_or_init(relations::RelationRegistry::empty),
            fk_labels: EMPTY_LABELS.get_or_init(std::collections::HashMap::new),
        }
    }
}

/// Snapshot the current registry from the in-memory schema cache.
/// Cheap: HashMap construction over a handful of models. Called on
/// every admin list / detail / delete handler that needs relation
/// awareness; no background task, no persistent cache.
fn current_registry() -> relations::RelationRegistry {
    match schema_cache::snapshot() {
        Some(c) => relations::RelationRegistry::from_schema(&c.schema),
        None => relations::RelationRegistry::empty(),
    }
}

/// Prefetch display labels for every `belongs_to` relation owned by
/// `T` whose target declares a `display_field`. Emits one `SELECT`
/// per FK column; IDs are collected from the current result set,
/// deduplicated, and batched into an `IN (…)` clause.
///
/// ## v1-NOTE — query strategy
///
/// This is a 1-plus-K strategy: one list query plus K single-column
/// FK lookups, where K is the number of FK columns on the model that
/// carry a `display_field`. Fine for realistic row counts and avoids
/// N+1. The first future optimisation is to rewrite the list query as
/// a `LEFT JOIN` onto every target carrying a display_field,
/// projecting `display_field` as an aliased column and collapsing
/// every round-trip into one. That change requires reworking the
/// list query builder, which is out of scope for this pass.
/// Dependent-reference counts per inverse relation for one target row.
/// Keyed by source-field qualified id: `"<source_model>.<source_field>"`.
/// Used by both the Phase 4 inverse panel renderer and the Phase 6
/// delete guard — they ask the same question ("how many rows point
/// at this one?") and share the same map.
type InverseCounts = std::collections::HashMap<String, i64>;

/// Count every row that holds a foreign key into `(target_model,
/// target_id)`. Issues **one `SELECT COUNT(*)` per incoming edge**;
/// the result is small (a handful of i64s) and cached into
/// [`InverseCounts`] for the rest of the request.
///
/// v1-NOTE: per-edge counting is the simplest correct shape. A
/// future version could batch these into a single UNION query or
/// push the counts into the existing list query as aggregated
/// sub-selects — same optimisation space as FK label prefetch.
async fn fetch_inverse_counts(
    db: &Db,
    target_model: &str,
    target_id: i64,
    registry: &relations::RelationRegistry,
) -> InverseCounts {
    use sqlx::Row;
    let mut out: InverseCounts = std::collections::HashMap::new();
    for inv in registry.has_many(target_model) {
        let sql = format!(
            "SELECT COUNT(*) AS rio_count FROM \"{table}\" WHERE \"{col}\" = ?",
            table = inv.source_table,
            col = inv.source_field,
        );
        let row = match sqlx::query(&sql).bind(target_id).fetch_one(db.pool()).await {
            Ok(r) => r,
            Err(_) => continue,
        };
        let count: i64 = row.try_get::<i64, _>("rio_count").unwrap_or_default();
        out.insert(format!("{}.{}", inv.source_model, inv.source_field), count);
    }
    out
}

/// Build one [`RelationFilterState`] per `belongs_to` relation on `T`.
/// Issues **one `SELECT id, <display> FROM <target> LIMIT cap+1` per
/// relation**. When the result hits `cap+1` rows the state falls
/// back to numeric-input mode and the admin renders the hint
/// explaining why. When the target has no declared `display_field`,
/// we also fall back to numeric input because there is no safe label
/// to render.
async fn build_relation_filters<T: AdminModel>(
    db: &Db,
    registry: &relations::RelationRegistry,
    query: &FormData,
) -> Vec<RelationFilterState> {
    use sqlx::Row;
    let mut out: Vec<RelationFilterState> = Vec::new();
    let cap = relations::RELATION_FILTER_DROPDOWN_CAP;
    for resolved in registry.belongs_to_of(T::singular_name()) {
        // Pull the currently-selected id from the query string.
        let current_value = query
            .get(&resolved.source_field)
            .and_then(|v| v.parse::<i64>().ok());

        // Determine the mode.
        let mode = match &resolved.target_display_field {
            None => RelationFilterMode::Numeric { too_many: false },
            Some(display_col) => {
                // LIMIT cap+1 so we can detect "above cap" without a
                // separate COUNT query.
                let sql = format!(
                    "SELECT id AS rio_id, \"{col}\" AS rio_label FROM \"{table}\" ORDER BY \"{col}\" ASC LIMIT {lim}",
                    col = display_col,
                    table = resolved.target_table,
                    lim = cap + 1,
                );
                let rows = match sqlx::query(&sql).fetch_all(db.pool()).await {
                    Ok(r) => r,
                    Err(_) => {
                        // Degrade: SQL failure → numeric fallback.
                        out.push(RelationFilterState {
                            field_name: resolved.source_field.clone(),
                            label: resolved.target_model.clone(),
                            current_value,
                            mode: RelationFilterMode::Numeric { too_many: false },
                        });
                        continue;
                    }
                };
                if rows.len() > cap {
                    RelationFilterMode::Numeric { too_many: true }
                } else {
                    let options: Vec<(i64, String)> = rows
                        .into_iter()
                        .map(|row| {
                            let id: i64 = row.try_get::<i64, _>("rio_id").unwrap_or_default();
                            let label: String = row
                                .try_get::<String, _>("rio_label")
                                .or_else(|_| {
                                    row.try_get::<i64, _>("rio_label").map(|n| n.to_string())
                                })
                                .or_else(|_| {
                                    row.try_get::<i32, _>("rio_label").map(|n| n.to_string())
                                })
                                .unwrap_or_default();
                            (id, label)
                        })
                        .collect();
                    RelationFilterMode::Dropdown { options }
                }
            }
        };

        out.push(RelationFilterState {
            field_name: resolved.source_field.clone(),
            label: resolved.target_model.clone(),
            current_value,
            mode,
        });
    }
    out
}

/// Build a FK-options map for use by admin create / edit forms.
/// Mirrors [`build_relation_filters`] in structure — same cap, same
/// SQL shape — but returns a flat per-field map so the form renderer
/// can look up options by field name without threading the richer
/// filter-state type through.
async fn fetch_form_relation_options<T: AdminModel>(
    db: &Db,
    registry: &relations::RelationRegistry,
) -> FormRelationOptions {
    use sqlx::Row;
    let mut out: FormRelationOptions = std::collections::HashMap::new();
    let cap = relations::RELATION_FILTER_DROPDOWN_CAP;
    for resolved in registry.belongs_to_of(T::singular_name()) {
        let Some(display_col) = &resolved.target_display_field else {
            continue;
        };
        let sql = format!(
            "SELECT id AS rio_id, \"{col}\" AS rio_label FROM \"{table}\" ORDER BY \"{col}\" ASC LIMIT {lim}",
            col = display_col,
            table = resolved.target_table,
            lim = cap + 1,
        );
        let rows = match sqlx::query(&sql).fetch_all(db.pool()).await {
            Ok(r) => r,
            Err(_) => continue,
        };
        if rows.len() > cap {
            // Too many options for a dropdown — fall back to numeric
            // input by omitting this field from the map.
            continue;
        }
        let options: Vec<(i64, String)> = rows
            .into_iter()
            .map(|row| {
                let id: i64 = row.try_get::<i64, _>("rio_id").unwrap_or_default();
                let label: String = row
                    .try_get::<String, _>("rio_label")
                    .or_else(|_| row.try_get::<i64, _>("rio_label").map(|n| n.to_string()))
                    .or_else(|_| row.try_get::<i32, _>("rio_label").map(|n| n.to_string()))
                    .unwrap_or_default();
                (id, label)
            })
            .collect();
        out.insert(resolved.source_field.clone(), options);
    }
    out
}

async fn fetch_fk_labels<T: AdminModel>(
    db: &Db,
    items: &[&T],
    registry: &relations::RelationRegistry,
) -> FkLabels {
    use sqlx::Row;
    let mut out: FkLabels = std::collections::HashMap::new();
    let source_model = T::singular_name();
    for f in T::FIELDS {
        let Some(resolved) = registry.belongs_to(source_model, f.name) else {
            continue;
        };
        let Some(display_col) = &resolved.target_display_field else {
            // No display_field declared for this relation. Don't
            // query — the renderer will fall back to #<id> and
            // explicit-is-better-than-implicit stops us from guessing
            // a column name.
            continue;
        };
        // Collect distinct ids; drop empty / unparseable values.
        let mut ids: Vec<i64> = items
            .iter()
            .filter_map(|it| it.field_display(f.name))
            .filter_map(|s| s.parse::<i64>().ok())
            .collect();
        ids.sort_unstable();
        ids.dedup();
        if ids.is_empty() {
            continue;
        }
        // SQLite's default max parameter count is 32766, so batching
        // any realistic list of ids fits in a single query.
        let placeholders: Vec<&'static str> = ids.iter().map(|_| "?").collect();
        let sql = format!(
            "SELECT id AS rio_id, \"{col}\" AS rio_label FROM \"{table}\" WHERE id IN ({ph})",
            col = display_col,
            table = resolved.target_table,
            ph = placeholders.join(","),
        );
        let mut q = sqlx::query(&sql);
        for id in &ids {
            q = q.bind(id);
        }
        let rows = match q.fetch_all(db.pool()).await {
            Ok(r) => r,
            // Degrade silently on any SQL error. The renderer falls
            // back to #<id>; failing a whole list page over one bad
            // display-field would be a net regression.
            Err(_) => continue,
        };
        let mut map: std::collections::HashMap<i64, String> = std::collections::HashMap::new();
        for row in rows {
            let id: i64 = row.try_get::<i64, _>("rio_id").unwrap_or_default();
            let label: String = row
                .try_get::<String, _>("rio_label")
                .or_else(|_| row.try_get::<i64, _>("rio_label").map(|n| n.to_string()))
                .or_else(|_| row.try_get::<i32, _>("rio_label").map(|n| n.to_string()))
                .or_else(|_| row.try_get::<bool, _>("rio_label").map(|b| b.to_string()))
                .unwrap_or_default();
            map.insert(id, label);
        }
        out.insert(f.name.to_string(), map);
    }
    out
}

fn list_response<T: AdminModel>(
    shell: Shell<'_>,
    items: &[&T],
    total: usize,
    filters: ListFilters<'_>,
    cell_ctx: &CellCtx<'_>,
) -> Response {
    let count = items.len();
    let singular = T::singular_name();
    let plural = T::DISPLAY_NAME;
    let admin_name = T::ADMIN_NAME;

    let page_actions = format!(
        r#"<a class="rio-btn rio-btn-primary" href="/admin/{name}/create">{icon}<span>Add {singular}</span></a>"#,
        name = escape_html(admin_name),
        singular = escape_html(singular),
        icon = icon_plus(),
    );

    // --- Empty states: two flavours ---
    // 1. Table has zero rows, period → encourage creation + show
    //    context-aware hint when the project has declared one.
    // 2. Filter returned zero of N → explain the filter is the reason.
    let body = if total == 0 {
        let hint_html = match empty_state_hint::<T>(intelligence::context_global()) {
            Some(h) => format!(r#"<p class="rio-empty-hint">{}</p>"#, escape_html(&h)),
            None => String::new(),
        };
        format!(
            r#"<div class="rio-card">
<div class="rio-empty">
<div class="rio-empty-icon">{icon}</div>
<h3>Start by adding your first {singular_lower}</h3>
<p>This table is empty. Create the first record to get started.</p>
{hint}
<a class="rio-btn rio-btn-primary" href="/admin/{name}/create">{plus}<span>Add {singular_lower}</span></a>
</div>
</div>"#,
            icon = icon_inbox(),
            name = escape_html(admin_name),
            plus = icon_plus(),
            singular_lower = escape_html(&singular.to_lowercase()),
            hint = hint_html,
        )
    } else {
        let toolbar = render_list_toolbar::<T>(&filters, count, total);
        // Change 4 — active filter chip row. Rendered OUTSIDE the
        // toolbar form and BEFORE the bulk-action form so neither
        // form owns it; each chip's `×` is a plain link that rebuilds
        // the URL without that one filter key.
        let chips = render_active_filter_chips(&filters, admin_name);

        if items.is_empty() {
            format!(
                r#"<div class="rio-table-wrap">
{toolbar}
{chips}
<div class="rio-empty">
<div class="rio-empty-icon">{icon}</div>
<h3>No records match these filters</h3>
<p>Try a different search term, clear the filters, or add a new {singular_lower}.</p>
<div class="rio-empty-actions">
<a class="rio-btn" href="/admin/{name}">{reset}<span>Clear filters</span></a>
<a class="rio-btn rio-btn-primary" href="/admin/{name}/create">{plus}<span>Add {singular_lower}</span></a>
</div>
</div>
</div>"#,
                icon = icon_search(),
                singular_lower = escape_html(&singular.to_lowercase()),
                name = escape_html(admin_name),
                reset = icon_arrow_left(),
                plus = icon_plus(),
            )
        } else {
            // Filter `T::FIELDS` through the visible-columns set
            // computed by the list handler. Declaration order is
            // preserved; hidden columns are simply not rendered in
            // this pass. (Row-expansion / hide-column UI is a later
            // change.)
            let visible_fields: Vec<&AdminField> = T::FIELDS
                .iter()
                .filter(|f| filters.visible_columns.contains(&f.name))
                .collect();
            // Change 5 — row expansion. Enabled only when the model
            // has fields outside the primary column set (Change 1);
            // otherwise there is nothing to reveal and the whole
            // expand UI is omitted.
            let has_hidden_fields = T::FIELDS.len() > visible_fields.len();
            let hidden_fields: Vec<&AdminField> = T::FIELDS
                .iter()
                .filter(|f| !filters.visible_columns.contains(&f.name))
                .collect();
            // Total column count drives the expand-row colspan. Based
            // on server-visible columns only; client-side display:none
            // from the Change 2 columns toggle is intentionally
            // ignored (browsers stretch the spanned cell to the
            // remaining visible width automatically).
            let colspan_total = visible_fields.len() + 3;
            // Each <th> and <td> carries `data-col="<field_name>"`
            // so the Columns toggle (Change 2) can match cells by
            // column name via `querySelectorAll('[data-col="…"]')`.
            // Checkbox and actions columns have no data-col and
            // are never touched by the toggle.
            let headers: String = visible_fields
                .iter()
                .map(|f| {
                    format!(
                        r#"<th data-col="{name}">{label}</th>"#,
                        name = escape_html(f.name),
                        label = escape_html(&humanise(f.name)),
                    )
                })
                .collect();
            let expand_header = if has_hidden_fields {
                r#"<th class="rio-cell-expand" aria-label="Expand"></th>"#.to_string()
            } else {
                String::new()
            };
            let rows: String = items
                .iter()
                .map(|item| {
                    let cells: String = visible_fields
                        .iter()
                        .map(|f| {
                            let cell = render_cell::<T>(f, *item, cell_ctx);
                            inject_data_col(&cell, f.name)
                        })
                        .collect();
                    let id = item.id();
                    // Icon + label actions — obvious to non-technical
                    // users. Delete uses a danger-ghost style so the
                    // destructive path reads but doesn't scream.
                    let row_actions = format!(
                        r#"<td class="rio-cell-actions">
<div class="rio-row-actions">
<a class="rio-btn rio-btn-sm" href="/admin/{name}/{id}/edit">{pencil}<span>Edit</span></a>
<a class="rio-btn rio-btn-sm rio-btn-danger-ghost" href="/admin/{name}/{id}/delete" rel="nofollow">{trash}<span>Delete</span></a>
</div>
</td>"#,
                        name = escape_html(admin_name),
                        id = id,
                        pencil = icon_pencil(),
                        trash = icon_trash(),
                    );
                    let checkbox = format!(
                        r#"<td class="rio-cell-check"><input type="checkbox" class="rio-bulk-row" value="{id}" aria-label="Select row {id}"></td>"#,
                    );
                    if !has_hidden_fields {
                        return format!("<tr>{checkbox}{cells}{row_actions}</tr>");
                    }
                    // Change 5 — build the paired main+expand rows.
                    // The expand row is always present in the DOM and
                    // carries the `hidden` attribute; the inline IIFE
                    // at the bottom of the page flips it on click.
                    let expand_cell = format!(
                        r#"<td class="rio-cell-expand"><button type="button" class="rio-expand-btn" data-expand-toggle aria-expanded="false" aria-label="Expand row {id}">&#9656;</button></td>"#,
                    );
                    let detail_fields: String = hidden_fields
                        .iter()
                        .map(|f| {
                            format!(
                                r#"<div class="rio-expand-field"><dt>{label}</dt><dd>{value}</dd></div>"#,
                                label = escape_html(&humanise(f.name)),
                                value = render_cell_inner::<T>(f, *item, cell_ctx),
                            )
                        })
                        .collect();
                    let expand_row = format!(
                        r#"<tr class="rio-row-expand" data-row-id="{id}" hidden><td colspan="{colspan}" class="rio-cell-expand-panel"><dl class="rio-expand-details">{fields}</dl></td></tr>"#,
                        id = id,
                        colspan = colspan_total,
                        fields = detail_fields,
                    );
                    format!(
                        r#"<tr class="rio-row-main" data-row-id="{id}">{expand_cell}{checkbox}{cells}{row_actions}</tr>{expand_row}"#,
                    )
                })
                .collect();

            let csrf = csrf_input(shell.csrf);
            let bulk_bar = format!(
                r#"<div class="rio-bulk-bar">
<label class="rio-bulk-label" for="rio-bulk-action">Action</label>
<select class="rio-select" id="rio-bulk-action" name="action">
<option value="">-- Select an action --</option>
<option value="delete">Delete selected {plural_lower}</option>
</select>
<button type="submit" class="rio-btn">Go</button>
<span class="rio-bulk-count" data-rio-bulk-count>0 selected</span>
</div>"#,
                plural_lower = escape_html(&plural.to_lowercase()),
            );

            format!(
                r#"<div class="rio-table-wrap">
{toolbar}
{chips}
<form method="post" action="/admin/{name}/bulk_action" class="rio-bulk-form">
{csrf}
<input type="hidden" name="_selected" value="">
{bulk_bar}
<table class="rio-table">
<thead><tr>{expand_header}<th class="rio-cell-check"><input type="checkbox" class="rio-bulk-all" aria-label="Select all"></th>{headers}<th aria-label="Actions"></th></tr></thead>
<tbody>{rows}</tbody>
</table>
</form>
<script>
(function(){{
var form=document.querySelector('.rio-bulk-form');
if(form){{
  var all=form.querySelector('.rio-bulk-all');
  var rows=form.querySelectorAll('.rio-bulk-row');
  var count=form.querySelector('[data-rio-bulk-count]');
  var hidden=form.querySelector('input[name="_selected"]');
  function collect(){{var ids=[];rows.forEach(function(cb){{if(cb.checked)ids.push(cb.value);}});return ids;}}
  function update(){{var ids=collect();if(hidden)hidden.value=ids.join(',');if(count)count.textContent=ids.length+' selected';}}
  if(all)all.addEventListener('change',function(){{rows.forEach(function(cb){{cb.checked=all.checked;}});update();}});
  rows.forEach(function(cb){{cb.addEventListener('change',update);}});
  form.addEventListener('submit',function(e){{update();var ids=collect();var act=form.querySelector('[name="action"]');if(!ids.length||!act.value){{e.preventDefault();alert('Select one or more rows and an action, then click Go.');}}}});
  update();
}}
// Columns toggle (Change 2) — outside-click closes the <details>,
// and checkbox changes flip `display: none` on the matching <th>
// and every matching <td> via `data-col` attribute. Checkbox and
// actions columns carry no `data-col`, so they're never touched.
document.addEventListener('click',function(e){{
  var d=document.querySelector('details.rio-cols-ctl[open]');
  if(!d)return;
  if(d.contains(e.target))return;
  d.open=false;
}});
document.addEventListener('change',function(e){{
  var cb=e.target&&e.target.closest?e.target.closest('.rio-cols-check'):null;
  if(!cb)return;
  var col=cb.getAttribute('data-col');
  if(!col)return;
  var esc=(window.CSS&&CSS.escape)?CSS.escape(col):col;
  document.querySelectorAll('[data-col="'+esc+'"]').forEach(function(cell){{
    cell.style.display=cb.checked?'':'none';
  }});
}});
// More filters panel toggle (Change 3) — plain hidden-attribute
// flip. Button carries `data-more-filters-toggle` and an
// `aria-controls` pointing at the panel id. No outside-click
// handler, no animation.
document.addEventListener('click',function(e){{
  var btn=e.target&&e.target.closest?e.target.closest('[data-more-filters-toggle]'):null;
  if(!btn)return;
  var id=btn.getAttribute('aria-controls');
  var panel=id?document.getElementById(id):null;
  if(!panel)return;
  var open=!panel.hasAttribute('hidden');
  if(open){{
    panel.setAttribute('hidden','');
    btn.setAttribute('aria-expanded','false');
  }}else{{
    panel.removeAttribute('hidden');
    btn.setAttribute('aria-expanded','true');
  }}
}});
// Row expansion toggle (Change 5) — the button lives in the first
// column of each `.rio-row-main`, the paired `.rio-row-expand` is
// its `nextElementSibling`. Flip the `hidden` attribute + chevron
// glyph + aria-expanded; nothing else.
document.addEventListener('click',function(e){{
  var btn=e.target&&e.target.closest?e.target.closest('[data-expand-toggle]'):null;
  if(!btn)return;
  var main=btn.closest('tr');
  if(!main)return;
  var panel=main.nextElementSibling;
  if(!panel||!panel.classList.contains('rio-row-expand'))return;
  var open=!panel.hasAttribute('hidden');
  if(open){{
    panel.setAttribute('hidden','');
    btn.setAttribute('aria-expanded','false');
    btn.textContent='\u25B8';
  }}else{{
    panel.removeAttribute('hidden');
    btn.setAttribute('aria-expanded','true');
    btn.textContent='\u25BE';
  }}
}});
}})();
</script>
</div>"#,
                name = escape_html(admin_name),
                expand_header = expand_header,
            )
        }
    };

    let crumbs: &[Crumb<'_>] = &[("Admin", Some("/admin")), (plural, None)];

    render_shell_page(
        &shell,
        200,
        plural,
        plural,
        Some(&format!(
            "Browse, search, and manage {}.",
            plural.to_lowercase()
        )),
        crumbs,
        &page_actions,
        &body,
    )
}

/// Render the search + filters + submit/reset toolbar. Posts as a GET
/// to the same list URL, so the current filter state is carried in the
/// URL and bookmarkable.
/// Render one relation-aware filter control. Dropdown when the
/// target carries a `display_field` and fits under the cap; numeric
/// input otherwise (with a hint explaining why).
fn render_relation_filter_control(state: &RelationFilterState) -> String {
    let field = escape_html(&state.field_name);
    let label = escape_html(&state.label);
    match &state.mode {
        RelationFilterMode::Dropdown { options } => {
            // "All patients", "All doctors" — pluralise the singular
            // model name so the placeholder reads like English.
            let placeholder = format!("All {}", pluralise_label(&state.label));
            let options_html: String = std::iter::once(format!(
                r#"<option value="">{}</option>"#,
                escape_html(&placeholder),
            ))
            .chain(options.iter().map(|(id, display)| {
                let selected = state.current_value == Some(*id);
                let mark = if selected { " selected" } else { "" };
                format!(
                    r#"<option value="{id}"{mark}>{display}</option>"#,
                    id = id,
                    mark = mark,
                    display = escape_html(display),
                )
            }))
            .collect();
            format!(
                r#"<select class="rio-select" name="{field}" aria-label="Filter by {label}">{options_html}</select>"#,
            )
        }
        RelationFilterMode::Numeric { too_many } => {
            let current = state
                .current_value
                .map(|v| v.to_string())
                .unwrap_or_default();
            // Two different hints so the operator knows the reason
            // for the numeric fallback: too many target rows to
            // dropdown, vs. no display_field declared on the target.
            let hint = if *too_many {
                format!(
                    r#"<span class="rio-field-hint">Too many options for a dropdown — enter the {label} ID directly.</span>"#,
                    label = label,
                )
            } else {
                format!(
                    r#"<span class="rio-field-hint">No display field declared for {label} — enter the ID directly.</span>"#,
                    label = label,
                )
            };
            format!(
                r#"<label class="rio-field" style="display:inline-flex; gap:var(--rio-s-1); align-items:center; margin:0">\
<span class="rio-field-label">{label} ID</span>\
<input class="rio-input" type="number" name="{field}" value="{current}" style="width:140px" aria-label="Filter by {label} id">\
{hint}\
</label>"#,
                label = label,
                field = field,
                current = escape_html(&current),
                hint = hint,
            )
        }
    }
}

/// Render the "Columns" control — a `<details>` summary button that
/// opens a checkbox panel listing every field on the model (Change
/// 2/5). Primary columns from [`default_list_columns`] start
/// checked; non-primary start unchecked. Toggling a primary
/// checkbox hides or shows that column client-side via a small
/// script at the bottom of the list page. Non-primary checkboxes
/// render in the panel for visibility but flipping them has no
/// effect in Change 2 — Change 1's server-side `visible_columns`
/// filter excludes those columns from the DOM entirely. Revealing
/// a non-primary column is a separate feature deferred to a later
/// change.
fn render_columns_control<T: AdminModel>(filters: &ListFilters<'_>) -> String {
    let rows: String = T::FIELDS
        .iter()
        .map(|f| {
            let is_visible = filters.visible_columns.contains(&f.name);
            let is_id = f.name == "id";
            let checked = if is_visible { " checked" } else { "" };
            let disabled = if is_id { " disabled" } else { "" };
            let mut tags: Vec<&'static str> = Vec::new();
            if is_visible {
                tags.push("primary");
            }
            if f.relation.is_some() {
                tags.push("relation");
            }
            let tag_html = if tags.is_empty() {
                String::new()
            } else {
                format!(" <small>{}</small>", tags.join(" · "))
            };
            format!(
                r#"<label class="rio-cols-panel-row"><input type="checkbox" class="rio-cols-check" data-col="{name}"{checked}{disabled}><span>{label}{tags}</span></label>"#,
                name = escape_html(f.name),
                label = escape_html(&humanise(f.name)),
                tags = tag_html,
            )
        })
        .collect();

    format!(
        r#"<details class="rio-cols-ctl"><summary class="rio-btn">Columns</summary><div class="rio-cols-panel">{rows}</div></details>"#,
    )
}

/// Build an admin list URL from a slice of (key, value) parameter
/// pairs (Change 4/5). No URL encoding is performed — values are
/// round-tripped raw, exactly as they entered the filter state from
/// the query string. Empty params → bare `/admin/<name>`; otherwise
/// `?k=v&k=v…`. Key ordering is preserved from the caller.
fn build_list_url(admin_name: &str, params: &[(String, String)]) -> String {
    if params.is_empty() {
        return format!("/admin/{}", admin_name);
    }
    let query: String = params
        .iter()
        .map(|(k, v)| format!("{}={}", k, v))
        .collect::<Vec<_>>()
        .join("&");
    format!("/admin/{}?{}", admin_name, query)
}

/// Collect the currently-active filter parameters as (key, value)
/// pairs in the canonical order `q, status, priority, <relations…>,
/// sort` (Change 4/5). Skips empty `q`. Each active relation filter
/// contributes one entry keyed by its FK column name. Sort is
/// included so chip removal preserves the user's sort choice.
fn current_filter_params(filters: &ListFilters<'_>) -> Vec<(String, String)> {
    let mut params: Vec<(String, String)> = Vec::new();
    if let Some(q) = filters.q.filter(|s| !s.is_empty()) {
        params.push(("q".to_string(), q.to_string()));
    }
    if let Some(s) = filters.status {
        params.push(("status".to_string(), s.to_string()));
    }
    if let Some(p) = filters.priority {
        params.push(("priority".to_string(), p.to_string()));
    }
    for r in filters.relation_filters {
        if let Some(id) = r.current_value {
            params.push((r.field_name.clone(), id.to_string()));
        }
    }
    if let Some(sort) = filters.sort {
        params.push(("sort".to_string(), sort.to_string()));
    }
    params
}

/// Render the "active filter chips" row (Change 4/5) — one chip per
/// chippable filter (search, status, priority, each active relation).
/// Sort is NOT chippable. Each chip's `×` link rebuilds the list URL
/// with that one key removed, preserving every other filter including
/// sort. A trailing "Clear all" link strips everything back to
/// `/admin/<name>`. Returns `""` when no chippable filter is active,
/// so the caller can drop the empty wrapper from the DOM.
fn render_active_filter_chips(filters: &ListFilters<'_>, admin_name: &str) -> String {
    let all_params = current_filter_params(filters);
    let remove_url = |exclude_key: &str| -> String {
        let kept: Vec<(String, String)> = all_params
            .iter()
            .filter(|(k, _)| k != exclude_key)
            .cloned()
            .collect();
        build_list_url(admin_name, &kept)
    };

    let mut chips: Vec<String> = Vec::new();

    if let Some(q) = filters.q.filter(|s| !s.is_empty()) {
        chips.push(format!(
            r#"<span class="admin-filter-chip"><span class="admin-filter-chip-label">Search:</span> <span class="admin-filter-chip-value">&quot;{value}&quot;</span> <a href="{href}" aria-label="Remove search filter">&times;</a></span>"#,
            value = escape_html(q),
            href = escape_html(&remove_url("q")),
        ));
    }
    if let Some(s) = filters.status {
        chips.push(format!(
            r#"<span class="admin-filter-chip"><span class="admin-filter-chip-label">Status:</span> <span class="admin-filter-chip-value">{value}</span> <a href="{href}" aria-label="Remove status filter">&times;</a></span>"#,
            value = escape_html(&humanise_enum_value(s)),
            href = escape_html(&remove_url("status")),
        ));
    }
    if let Some(p) = filters.priority {
        chips.push(format!(
            r#"<span class="admin-filter-chip"><span class="admin-filter-chip-label">Priority:</span> <span class="admin-filter-chip-value">{value}</span> <a href="{href}" aria-label="Remove priority filter">&times;</a></span>"#,
            value = escape_html(p),
            href = escape_html(&remove_url("priority")),
        ));
    }
    for r in filters.relation_filters {
        if let Some(id) = r.current_value {
            let display = match &r.mode {
                RelationFilterMode::Dropdown { options } => options
                    .iter()
                    .find(|(opt_id, _)| *opt_id == id)
                    .map(|(_, name)| name.clone())
                    .unwrap_or_else(|| format!("#{}", id)),
                RelationFilterMode::Numeric { .. } => format!("#{}", id),
            };
            chips.push(format!(
                r#"<span class="admin-filter-chip"><span class="admin-filter-chip-label">{label}:</span> <span class="admin-filter-chip-value">{value}</span> <a href="{href}" aria-label="Remove {label} filter">&times;</a></span>"#,
                label = escape_html(&r.label),
                value = escape_html(&display),
                href = escape_html(&remove_url(&r.field_name)),
            ));
        }
    }

    if chips.is_empty() {
        return String::new();
    }

    format!(
        r#"<div class="admin-filter-chips">{chips}<a class="admin-filter-clear-all" href="/admin/{name}">Clear all</a></div>"#,
        chips = chips.join(""),
        name = escape_html(admin_name),
    )
}

/// Render the "More filters" secondary panel (Change 3). Returns
/// `""` when no secondary filter control is available on the model
/// — in which case the toolbar also omits the "More filters"
/// button, keeping the DOM minimal on filter-less models. Otherwise
/// returns a `hidden` `<div>` containing a 3-column grid of secondary
/// filter controls. Spec: panel defaults to hidden; JS toggles it.
fn render_more_filters_panel(
    status_select: &str,
    priority_select: &str,
    secondary_relations_html: &str,
) -> String {
    if status_select.is_empty() && priority_select.is_empty() && secondary_relations_html.is_empty()
    {
        return String::new();
    }
    format!(
        r#"<div class="admin-list-more-filters" id="more-filters-panel" hidden><div class="admin-filter-grid">{status}{priority}{relations}</div></div>"#,
        status = status_select,
        priority = priority_select,
        relations = secondary_relations_html,
    )
}

fn render_list_toolbar<T: AdminModel>(
    filters: &ListFilters<'_>,
    shown: usize,
    total: usize,
) -> String {
    let admin_name = T::ADMIN_NAME;
    let plural = T::DISPLAY_NAME;

    let q_value = filters.q.map(escape_html).unwrap_or_default();

    // Status filter dropdown — only rendered when the model has a
    // String field named "status" (detected by non-empty options).
    // Values stay raw (`checked_in`, `no_show`) so form round-trip
    // works; labels are humanised ("Checked in", "No show") so the
    // dropdown reads like English rather than database fields.
    let status_select = if !filters.status_options.is_empty() {
        let options: String =
            std::iter::once(r#"<option value="">All statuses</option>"#.to_string())
                .chain(filters.status_options.iter().map(|v| {
                    let selected = if filters.status.map(|s| s == v).unwrap_or(false) {
                        " selected"
                    } else {
                        ""
                    };
                    format!(
                        r#"<option value="{v}"{selected}>{label}</option>"#,
                        v = escape_html(v),
                        label = escape_html(&humanise_enum_value(v)),
                    )
                }))
                .collect();
        format!(
            r#"<select class="rio-select" name="status" aria-label="Filter by status">{options}</select>"#,
        )
    } else {
        String::new()
    };

    // Priority filter — numeric. Sort the options numerically so the
    // dropdown reads 1, 2, …, 10 (not 1, 10, 2 — the default string
    // sort from `distinct_values`).
    let priority_select = if !filters.priority_options.is_empty() {
        let mut sorted_priorities: Vec<&String> = filters.priority_options.iter().collect();
        sorted_priorities.sort_by(|a, b| {
            let na: Option<i64> = a.parse().ok();
            let nb: Option<i64> = b.parse().ok();
            match (na, nb) {
                (Some(x), Some(y)) => x.cmp(&y),
                _ => a.cmp(b),
            }
        });
        let options: String =
            std::iter::once(r#"<option value="">All priorities</option>"#.to_string())
                .chain(sorted_priorities.iter().map(|v| {
                    let selected = if filters.priority.map(|p| p == v.as_str()).unwrap_or(false) {
                        " selected"
                    } else {
                        ""
                    };
                    format!(
                        r#"<option value="{v}"{selected}>Priority {v}</option>"#,
                        v = escape_html(v),
                    )
                }))
                .collect();
        format!(
            r#"<select class="rio-select" name="priority" aria-label="Filter by priority">{options}</select>"#,
        )
    } else {
        String::new()
    };

    // Phase 5 — relation-aware filters. The FIRST belongs_to on the
    // model is promoted to the primary toolbar; the rest drop into
    // the "More filters" panel below (Change 3).
    let (primary_relation_html, secondary_relations_html): (String, String) = {
        let mut iter = filters.relation_filters.iter();
        let first = iter
            .next()
            .map(render_relation_filter_control)
            .unwrap_or_default();
        let rest: String = iter.map(render_relation_filter_control).collect();
        (first, rest)
    };

    // Count active SECONDARY filters for the "More filters (N)"
    // button label. Excludes search, the primary relation filter,
    // and sort per spec §5.4.
    let secondary_active_count: usize = filters.status.is_some() as usize
        + filters.priority.is_some() as usize
        + filters
            .relation_filters
            .iter()
            .skip(1)
            .filter(|r| r.current_value.is_some())
            .count();

    // Render the "More filters" panel + button only when at least
    // one secondary filter control exists on this model. If the
    // panel would be empty, both the button and the <div> are
    // omitted from the DOM entirely (spec §Q3 decision).
    let more_filters_panel_html =
        render_more_filters_panel(&status_select, &priority_select, &secondary_relations_html);
    let more_filters_btn = if more_filters_panel_html.is_empty() {
        String::new()
    } else {
        let label = if secondary_active_count == 0 {
            "More filters".to_string()
        } else {
            format!("More filters ({secondary_active_count})")
        };
        format!(
            r#"<button type="button" class="rio-btn" data-more-filters-toggle aria-controls="more-filters-panel" aria-expanded="false">{label}</button>"#,
        )
    };

    let reset_btn = if filters.is_active() {
        format!(
            r#"<a class="rio-btn rio-btn-ghost" href="/admin/{name}">Reset</a>"#,
            name = escape_html(admin_name),
        )
    } else {
        String::new()
    };

    // Sort dropdown — always rendered. Pinned vocabulary in
    // `SORT_OPTIONS` keeps the options identical across every admin
    // list in every project, so the toolbar shape is predictable for
    // operators moving between models.
    let sort_select = {
        let current = filters.sort.unwrap_or("newest");
        let options: String = SORT_OPTIONS
            .iter()
            .map(|(value, label)| {
                let sel = if *value == current { " selected" } else { "" };
                format!(
                    r#"<option value="{v}"{sel}>{l}</option>"#,
                    v = escape_html(value),
                    l = escape_html(label),
                )
            })
            .collect();
        format!(
            r#"<select class="rio-select rio-select-sort" name="sort" aria-label="Sort records">{options}</select>"#,
        )
    };

    let count_label = if filters.is_active() {
        format!("Showing {shown} of {total}")
    } else if total == 1 {
        "1 record".to_string()
    } else {
        format!("{total} records")
    };

    // Search-intent badge. Only render when the user has typed
    // something that the classifier routes away from plain text —
    // "Interpreted as ID", "Interpreted as personnummer", etc. —
    // so the operator sees what the list handler is actually doing.
    let intent_badge = filters
        .q
        .filter(|q| !q.is_empty())
        .map(|q| match intelligence::classify_search(q) {
            intelligence::SearchIntent::Text(_) => String::new(),
            other => format!(
                r#"<span class="rio-search-intent">Interpreted as: {}</span>"#,
                escape_html(other.label()),
            ),
        })
        .unwrap_or_default();

    // Columns control — sits inside .rio-toolbar-actions, right
    // after the "More filters" button (Change 3). Native <details>
    // whose panel is positioned below the summary; open/close is
    // browser-default, outside-click closes it via a small JS
    // listener at the bottom of the list page.
    let columns_control = render_columns_control::<T>(filters);

    format!(
        r#"<form class="rio-table-toolbar" method="get" action="/admin/{name}" role="search" aria-label="Search {plural}">
<div class="rio-search">
{search_icon}
<input type="search" name="q" value="{q}" placeholder="Search {plural_lower}…" aria-label="Search text">
{intent}
</div>
{primary_relation}
{sort}
<div class="rio-toolbar-actions">
<button type="submit" class="rio-btn rio-btn-primary">{submit_icon}<span>Search</span></button>
{more_filters_btn}
{reset}
{columns}
</div>
<div class="rio-count">{count}</div>
{more_filters_panel}
</form>"#,
        name = escape_html(admin_name),
        plural = escape_html(plural),
        plural_lower = escape_html(&plural.to_lowercase()),
        search_icon = icon_search(),
        q = q_value,
        intent = intent_badge,
        primary_relation = primary_relation_html,
        sort = sort_select,
        submit_icon = icon_search(),
        more_filters_btn = more_filters_btn,
        reset = reset_btn,
        columns = columns_control,
        count = escape_html(&count_label),
        more_filters_panel = more_filters_panel_html,
    )
}

/// In-memory substring match — scans every String field, plus the
/// id, for `needle` (case-insensitive). Good enough for the dev
/// admin's typical row counts; DB-backed LIKE comes once a project
/// adds pagination.
fn matches_query<T: AdminModel>(item: &T, needle: &str) -> bool {
    let needle = needle.to_lowercase();
    if item.id().to_string().contains(&needle) {
        return true;
    }
    for f in T::FIELDS.iter() {
        if matches!(f.ty, FieldType::String) {
            if let Some(v) = item.field_display(f.name) {
                if v.to_lowercase().contains(&needle) {
                    return true;
                }
            }
        }
    }
    false
}

/// Collect the distinct non-empty values for a named field, sorted.
/// Returns empty when the field doesn't exist on the model — which
/// lets the toolbar renderer skip the filter entirely.
fn distinct_values<T: AdminModel>(items: &[T], field_name: &str) -> Vec<String> {
    if !T::FIELDS.iter().any(|f| f.name == field_name) {
        return Vec::new();
    }
    let mut set: std::collections::BTreeSet<String> = std::collections::BTreeSet::new();
    for item in items {
        if let Some(v) = item.field_display(field_name) {
            if !v.is_empty() {
                set.insert(v);
            }
        }
    }
    set.into_iter().collect()
}

/// Map common status / lifecycle strings to a semantic pill colour.
/// Unknown values fall through to neutral slate. Keeping this small
/// and known is deliberate — no ad-hoc colour explosions.
fn status_pill_class(value: &str) -> &'static str {
    match value {
        "done" | "complete" | "completed" | "finished" | "resolved" => "rio-pill rio-pill-emerald",
        "active" | "approved" | "published" | "live" => "rio-pill rio-pill-emerald",
        "pending" | "todo" | "queued" | "open" | "new" => "rio-pill rio-pill-amber",
        "in_progress" | "doing" | "working" | "review" | "in_review" => "rio-pill rio-pill-indigo",
        "archived" | "inactive" | "closed" | "cancelled" | "canceled" => "rio-pill rio-pill-slate",
        "blocked" | "failed" | "rejected" | "error" => "rio-pill rio-pill-rose",
        _ => "rio-pill rio-pill-slate",
    }
}

/// Render one table cell with styling driven by the field's role and
/// type. Designed for scanning: id monospace-muted, primary column
/// bolded, bools + status strings become pills, nullable empties
/// render as a subtle em-dash.
///
/// Relation-aware: when the field carries `#[rustio(belongs_to =
/// "…")]` metadata and the registry has prefetched a display label,
/// the cell renders as a link to the target plus the muted `#<id>`.
/// When `display_field` is not declared, the cell renders `#<id>` as
/// a link. No label inference is ever attempted.
///
/// Insert `data-col="{col}"` into the opening `<td` tag of a
/// cell-rendering so the Columns-toggle JS can target the cell by
/// column name (Change 2/5). Non-invasive — preserves the rest of
/// the cell verbatim; returns the original string if the shape is
/// unexpected (e.g. a future render_cell variant that doesn't start
/// with `<td`).
fn inject_data_col(cell: &str, col: &str) -> String {
    let trimmed_offset = cell.len() - cell.trim_start().len();
    let rest = &cell[trimmed_offset..];
    if !rest.starts_with("<td") {
        return cell.to_string();
    }
    let (leading_ws, after_ws) = cell.split_at(trimmed_offset);
    // after_ws starts with "<td"; splice ` data-col="..."` after `<td`.
    let after_td = &after_ws[3..];
    format!(
        r#"{leading_ws}<td data-col="{col}"{after_td}"#,
        col = escape_html(col),
    )
}

fn render_cell<T: AdminModel>(f: &AdminField, item: &T, ctx: &CellCtx<'_>) -> String {
    let value = item.field_display(f.name).unwrap_or_default();
    if f.name == "id" {
        return format!(r#"<td class="rio-cell-id">#{}</td>"#, escape_html(&value));
    }
    if value.is_empty() && f.nullable {
        return r#"<td class="rio-cell-muted">—</td>"#.to_string();
    }
    // Relation branch: if this field is a FK to another model, render
    // a link to the target admin page plus the id. Uses the prefetched
    // label map; never re-queries the DB here.
    if let Some(resolved) = ctx.registry.belongs_to(T::singular_name(), f.name) {
        if let Ok(id) = value.parse::<i64>() {
            let label = ctx.fk_labels.get(f.name).and_then(|m| m.get(&id));
            let admin = escape_html(&resolved.target_admin_name);
            return match (label, &resolved.target_display_field) {
                // Best case: label resolved, render name + muted id.
                (Some(name), _) => format!(
                    r#"<td class="rio-cell-muted"><a href="/admin/{admin}/{id}">{name}</a> <span class="rio-cell-id">#{id}</span></td>"#,
                    admin = admin,
                    id = id,
                    name = escape_html(name),
                ),
                // display_field declared but target missing (deleted
                // row, stale schema). Link still works — the target
                // admin will produce a 404.
                (None, Some(_)) => format!(
                    r#"<td class="rio-cell-muted"><a href="/admin/{admin}/{id}">#{id}</a></td>"#,
                    admin = admin,
                    id = id,
                ),
                // No display_field declared → explicit #<id> with
                // link. We never guess a column.
                (None, None) => format!(
                    r#"<td class="rio-cell-muted"><a href="/admin/{admin}/{id}">#{id}</a></td>"#,
                    admin = admin,
                    id = id,
                ),
            };
        }
        // FK column but the value didn't parse as an i64. Fall
        // through to the default numeric render.
    }
    // Sensitive fields (personnummer, email under GDPR, patient_id under
    // healthcare, …) are masked by default; a tiny inline toggle
    // restores the real value when the reviewer clicks "show".
    let ctx = intelligence::context_global();
    let ui = intelligence::field_ui_metadata(f, ctx);
    if ui.sensitive && !value.is_empty() {
        let masked = intelligence::mask_pii(&value);
        return format!(
            r#"<td class="rio-cell-muted">\
<span class="rio-pii" data-value="{real}" data-mask="{mask}" data-hidden="1">{mask}</span>\
<button class="rio-pii-toggle" type="button" aria-label="Reveal value">show</button>\
</td>"#,
            real = escape_html(&value),
            mask = escape_html(&masked),
        );
    }
    if matches!(f.ty, FieldType::Bool) {
        let (cls, label) = match value.as_str() {
            "true" => ("rio-pill rio-pill-emerald", "active"),
            "false" => ("rio-pill rio-pill-slate", "inactive"),
            other => ("rio-pill rio-pill-slate", other),
        };
        return format!(
            r#"<td><span class="{cls}">{}</span></td>"#,
            escape_html(label)
        );
    }
    // Status-like String fields get a coloured pill. Keeps tables
    // scannable at a glance without requiring per-project config.
    if f.name == "status" && matches!(f.ty, FieldType::String) {
        let cls = status_pill_class(&value);
        let label = value.replace('_', " ");
        return format!(
            r#"<td><span class="{cls}">{}</span></td>"#,
            escape_html(&label)
        );
    }
    // Numeric fields get tabular numerics + muted colour.
    if matches!(f.ty, FieldType::I32 | FieldType::I64) {
        return format!(r#"<td class="rio-cell-num">{}</td>"#, escape_html(&value));
    }
    // First non-id field becomes the primary-weight cell.
    let is_primary = f.name != "id"
        && T::FIELDS
            .iter()
            .find(|x| x.name != "id")
            .map(|first| first.name == f.name)
            .unwrap_or(false);
    let cls = if is_primary {
        "rio-cell-primary"
    } else {
        "rio-cell-muted"
    };
    format!(r#"<td class="{cls}">{}</td>"#, escape_html(&value))
}

/// Strip the `<td …>` wrapper from a [`render_cell`] output so the
/// inner value can be reused inside the row-expansion panel
/// (Change 5/5). Relies on the invariant that `render_cell` always
/// returns a single `<td …>INNER</td>` string — do not change that
/// shape without updating this helper.
fn render_cell_inner<T: AdminModel>(f: &AdminField, item: &T, ctx: &CellCtx<'_>) -> String {
    let cell = render_cell::<T>(f, item, ctx);
    let start = cell.find('>').map(|i| i + 1).unwrap_or(0);
    let end = cell.rfind("</td>").unwrap_or(cell.len());
    cell[start..end].to_string()
}

// ---------------------------------------------------------------------------
// Form page (create / edit)
// ---------------------------------------------------------------------------

enum FormMode<'a, T: AdminModel> {
    Create,
    Edit { id: i64, item: &'a T },
}

fn form_response<T: AdminModel>(
    shell: Shell<'_>,
    mode: FormMode<'_, T>,
    cell_ctx: &CellCtx<'_>,
    inverse_counts: &InverseCounts,
    form_options: &FormRelationOptions,
) -> Response {
    let plural = T::DISPLAY_NAME;
    let singular = T::singular_name();
    let admin_name = T::ADMIN_NAME;

    let (heading, doc_title, subtitle, action, back_label) = match &mode {
        FormMode::Create => (
            format!("New {singular}"),
            format!("New {singular}"),
            format!("Create a new {} record.", singular.to_lowercase()),
            format!("/admin/{admin_name}/create"),
            format!("Back to {}", plural.to_lowercase()),
        ),
        FormMode::Edit { id, .. } => (
            format!("Edit {singular}"),
            format!("Edit {singular} #{id}"),
            format!("Update this {} record.", singular.to_lowercase()),
            format!("/admin/{admin_name}/{id}/edit"),
            format!("Back to {}", plural.to_lowercase()),
        ),
    };

    let fields: String = T::FIELDS
        .iter()
        .filter(|f| f.editable)
        .map(|f| {
            render_field_block::<T>(
                f,
                match &mode {
                    FormMode::Create => None,
                    FormMode::Edit { item, .. } => Some(*item),
                },
                cell_ctx,
                form_options,
            )
        })
        .collect();

    let meta_block = match &mode {
        FormMode::Create => String::new(),
        FormMode::Edit { id, item } => render_meta::<T>(*id, item),
    };

    // Phase 4 — inverse relation panels. Shown only on the Edit page
    // (Create has nothing to count against). Each `has_many` pointing
    // at this model becomes a "<plural> (N)" card linking to the
    // filtered list on that source model. v1 renders counts only; a
    // future pass can add preview rows and in-page navigation.
    let inverse_panel = match &mode {
        FormMode::Create => String::new(),
        FormMode::Edit { id, .. } => {
            render_inverse_panel::<T>(cell_ctx.registry, inverse_counts, *id)
        }
    };

    let danger_zone = match &mode {
        FormMode::Create => String::new(),
        FormMode::Edit { id, .. } => format!(
            r#"<section class="rio-danger-zone">
<div class="rio-danger-copy">
<h3 class="rio-danger-title">{warn}<span>Delete this {singular}</span></h3>
<p class="rio-danger-hint">Permanently removes this record. Rows that reference it with <code>ON DELETE CASCADE</code> will also be deleted.</p>
</div>
<a class="rio-btn rio-btn-danger" href="/admin/{name}/{id}/delete" rel="nofollow">{trash}<span>Delete record</span></a>
</section>"#,
            warn = icon_triangle_alert(),
            singular = escape_html(&singular.to_lowercase()),
            name = escape_html(admin_name),
            id = id,
            trash = icon_trash(),
        ),
    };

    let csrf_hidden = csrf_input(shell.csrf);

    let body = format!(
        r#"{meta}
<form class="rio-card rio-form" method="post" action="{action}" autocomplete="off">
{csrf}
<div class="rio-form-section">
<h2 class="rio-form-section-title">Details</h2>
<p class="rio-form-section-hint">Fields marked optional accept an empty value.</p>
{fields}
</div>
<div class="rio-form-footer">
<a class="rio-btn rio-btn-ghost" href="/admin/{name}">{back_icon}<span>{back_label}</span></a>
<div class="rio-footer-actions">
<a class="rio-btn" href="/admin/{name}">Cancel</a>
<button class="rio-btn rio-btn-primary" type="submit">Save</button>
</div>
</div>
</form>
{inverse}
{danger}"#,
        meta = meta_block,
        action = escape_html(&action),
        csrf = csrf_hidden,
        fields = fields,
        name = escape_html(admin_name),
        back_icon = icon_arrow_left(),
        back_label = escape_html(&back_label),
        inverse = inverse_panel,
        danger = danger_zone,
    );

    // Bind the plural href to a local `String` so the breadcrumbs
    // array can borrow into it. Without this, `format!` creates a
    // temporary that's dropped before the render call.
    let plural_href = format!("/admin/{admin_name}");
    let crumbs: Vec<Crumb<'_>> = match &mode {
        FormMode::Create => vec![
            ("Admin", Some("/admin")),
            (plural, Some(plural_href.as_str())),
            ("New", None),
        ],
        FormMode::Edit { .. } => vec![
            ("Admin", Some("/admin")),
            (plural, Some(plural_href.as_str())),
            ("Edit", None),
        ],
    };

    // On edit mode, surface the "History" action in the page header
    // so operators can navigate to the per-object history page
    // without scrolling down to the metadata block.
    let page_actions = match &mode {
        FormMode::Create => String::new(),
        FormMode::Edit { id, .. } => format!(
            r#"<a class="rio-btn" href="/admin/{name}/{id}/history">History</a>"#,
            name = escape_html(admin_name),
            id = id,
        ),
    };

    render_shell_page(
        &shell,
        200,
        &doc_title,
        &heading,
        Some(&subtitle),
        &crumbs,
        &page_actions,
        &body,
    )
}

/// Render a `(label, input)` block for one editable admin field.
///
/// Relation-aware: when the field carries `#[rustio(belongs_to =
/// "…")]` and we're rendering an existing row (Edit mode), a small
/// "linked: <Name> (#<id>)" hint appears under the input. The input
/// itself stays numeric in v1 — a proper relation picker is future
/// work.
fn render_field_block<T: AdminModel>(
    f: &AdminField,
    item: Option<&T>,
    cell_ctx: &CellCtx<'_>,
    form_options: &FormRelationOptions,
) -> String {
    let name = escape_html(f.name);
    let mut ui = intelligence::field_ui_metadata(f, intelligence::context_global());
    // When the field carries a declared relation, our own richer
    // `Linked: <Name>` hint replaces the generic "Foreign-key id"
    // hint from the intelligence layer. The relation label also
    // drops its trailing " Id" so the field reads as "Patient"
    // not "Patient Id".
    if f.relation.is_some() {
        ui.hint = None;
        ui.label = field_label(f);
    }
    let input = render_field::<T>(f, item, ui.placeholder.as_deref(), form_options);

    // Bool fields render as a single checkbox row for compactness.
    if matches!(f.ty, FieldType::Bool) {
        return format!(
            r#"<div class="rio-field rio-field-row-checkbox">
{input}
<label for="_{name}">{label}</label>
</div>"#,
            input = input,
            name = name,
            label = escape_html(&ui.label),
        );
    }

    let optional_mark = if f.nullable {
        r#"<span class="rio-field-optional">optional</span>"#.to_string()
    } else {
        String::new()
    };
    let sensitive_mark = if ui.sensitive {
        let note = ui
            .sensitivity_note
            .as_deref()
            .unwrap_or("Personal data — handle with care.");
        format!(
            r#"<span class="rio-field-sensitive" title="{note}">🔒 PII</span>"#,
            note = escape_html(note),
        )
    } else {
        String::new()
    };
    let hint_html = match ui.hint.as_deref() {
        Some(h) => format!(r#"<p class="rio-field-hint">{}</p>"#, escape_html(h),),
        None => String::new(),
    };

    // Relation hint: "Linked: <Name> (#<id>)" under the numeric input.
    // Rendered only when the field has `#[rustio(belongs_to = …)]`,
    // we're editing an existing row, and the FK value parses. Stays
    // silent when the id is empty, unparseable, or the label
    // prefetch returned nothing.
    let relation_hint = render_relation_hint::<T>(f, item, cell_ctx);

    format!(
        r#"<div class="rio-field">
<label for="_{name}">{label}{optional}{sensitive}</label>
{input}
{rel}
{hint}
</div>"#,
        name = name,
        label = escape_html(&ui.label),
        optional = optional_mark,
        sensitive = sensitive_mark,
        rel = relation_hint,
        hint = hint_html,
    )
}

/// Render a small `<p>` hint below a FK input showing the currently
/// linked target. Empty string when:
///   - the field has no `belongs_to` annotation,
///   - the registry doesn't know about the model / field,
///   - there is no current item (Create mode),
///   - the value doesn't parse as an i64.
fn render_relation_hint<T: AdminModel>(
    f: &AdminField,
    item: Option<&T>,
    cell_ctx: &CellCtx<'_>,
) -> String {
    let Some(item) = item else {
        return String::new();
    };
    if f.relation.is_none() {
        return String::new();
    }
    let Some(resolved) = cell_ctx.registry.belongs_to(T::singular_name(), f.name) else {
        return String::new();
    };
    let Some(value) = item.field_display(f.name) else {
        return String::new();
    };
    let Ok(id) = value.parse::<i64>() else {
        return String::new();
    };
    let label = cell_ctx.fk_labels.get(f.name).and_then(|m| m.get(&id));
    let admin = escape_html(&resolved.target_admin_name);
    match (label, &resolved.target_display_field) {
        (Some(name), _) => format!(
            r#"<p class="rio-field-hint">Linked: <a href="/admin/{admin}/{id}">{name}</a> <span class="rio-cell-id">#{id}</span></p>"#,
            admin = admin,
            id = id,
            name = escape_html(name),
        ),
        (None, _) => format!(
            r#"<p class="rio-field-hint">Linked: <a href="/admin/{admin}/{id}">#{id}</a></p>"#,
            admin = admin,
            id = id,
        ),
    }
}

/// Substring-match the well-known SQLite error message that fires
/// on a FK constraint violation. Stable across SQLite 3.x and
/// surfaced identically by every sqlx version we support. Fragile
/// against localisation, but SQLite does not localise driver error
/// messages.
fn is_foreign_key_violation(e: &Error) -> bool {
    matches!(e, Error::Internal(msg) if msg.contains("FOREIGN KEY constraint failed"))
}

/// Phase 6 — 409 Conflict page rendered when a delete is refused
/// because other rows reference this one. Lists every blocking
/// inverse with its count and a link to the filtered list on the
/// source model.
fn render_delete_blocked_page<T: AdminModel>(
    shell: &Shell<'_>,
    target_id: i64,
    target_primary: &str,
    blockers: &[(&relations::InverseRelation, i64)],
) -> Response {
    let singular = T::singular_name();
    let admin_name = T::ADMIN_NAME;
    let plural = T::DISPLAY_NAME;
    let subject = if target_primary.is_empty() {
        format!("{singular} #{target_id}")
    } else {
        format!("{target_primary} (#{target_id})")
    };

    let rows: String = blockers
        .iter()
        .map(|(inv, count)| {
            let filter_url = format!(
                "/admin/{}?{}={}",
                inv.source_admin_name,
                urlencoding_light(&inv.source_field),
                target_id,
            );
            format!(
                r#"<li class="rio-dashboard-alert"><div><strong>{label}</strong> — referenced by <strong>{count}</strong> row{plural_s} via <code>{field}</code></div><a class="rio-btn rio-btn-sm" href="{url}">Open {label_lower}</a></li>"#,
                label = escape_html(&inv.source_display_name),
                label_lower = escape_html(&inv.source_display_name.to_lowercase()),
                field = escape_html(&inv.source_field),
                count = count,
                plural_s = if *count == 1 { "" } else { "s" },
                url = escape_html(&filter_url),
            )
        })
        .collect();

    let back_href = format!("/admin/{}", admin_name);
    let body = format!(
        r#"<section class="rio-card">
<div class="rio-card-header">
<h2 class="rio-card-title">Cannot delete {subject}</h2>
<p class="rio-card-subtitle">Other records reference this one. Remove or reassign them first, then retry the delete.</p>
</div>
<ul class="rio-dashboard-alerts" style="list-style:none; margin:0; padding:var(--rio-card-pad)">
{rows}
</ul>
<div class="rio-form-footer">
<a class="rio-btn" href="{back}">Back to {plural_lower}</a>
</div>
</section>"#,
        subject = escape_html(&subject),
        rows = rows,
        back = escape_html(&back_href),
        plural_lower = escape_html(&plural.to_lowercase()),
    );

    let plural_href = back_href.clone();
    let crumbs: Vec<Crumb<'_>> = vec![
        ("Admin", Some("/admin")),
        (plural, Some(plural_href.as_str())),
        ("Delete blocked", None),
    ];
    let doc_title = format!("Cannot delete {subject}");
    render_shell_page(
        shell,
        409,
        &doc_title,
        "Delete blocked",
        Some("Remove the dependent references first, then retry."),
        &crumbs,
        "",
        &body,
    )
}

/// Phase 4 — render a "Related" block listing every `has_many`
/// inverse of the current model with its row count and a link to
/// the filtered list on the source model.
///
/// v1 shows counts only. Future evolution (per the module header in
/// `admin/relations.rs`):
///   - preview rows (top-N newest),
///   - in-page expand rather than link-out,
///   - per-panel search.
fn render_inverse_panel<T: AdminModel>(
    registry: &relations::RelationRegistry,
    counts: &InverseCounts,
    target_id: i64,
) -> String {
    let inverses = registry.has_many(T::singular_name());
    if inverses.is_empty() {
        return String::new();
    }
    let cards: String = inverses
        .iter()
        .map(|inv| {
            let key = format!("{}.{}", inv.source_model, inv.source_field);
            let count = counts.get(&key).copied().unwrap_or(0);
            let label = inv.source_display_name.to_string();
            // `source_field` is guaranteed snake_case by the Rust
            // identifier rules, so URL-encoding is moot. Kept as a
            // helper call for future-proofing.
            let filter_url = format!(
                "/admin/{}?{}={}",
                inv.source_admin_name,
                urlencoding_light(&inv.source_field),
                target_id,
            );
            format!(
                r#"<li><a href="{url}" class="rio-suggestion-card"><div><strong>{label}</strong> <span class="rio-cell-id">({count})</span></div><div class="rio-cell-muted">via {field}</div></a></li>"#,
                url = escape_html(&filter_url),
                label = escape_html(&label),
                count = count,
                field = escape_html(&inv.source_field),
            )
        })
        .collect();
    format!(
        r#"<section class="rio-card rio-related">
<div class="rio-card-header">
<h2 class="rio-card-title">Related</h2>
<p class="rio-card-subtitle">Incoming references to this record.</p>
</div>
<ul class="rio-related-grid">
{cards}
</ul>
</section>"#,
        cards = cards,
    )
}

/// Minimal URL-path encoder. Doesn't depend on the `url` crate —
/// only replaces the handful of characters that would break an
/// unquoted query-string key or value. All our source_field names
/// are snake_case idents (already safe) so this is really just a
/// belt-and-suspenders measure for future schemas.
fn urlencoding_light(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for ch in s.chars() {
        match ch {
            ' ' => out.push_str("%20"),
            '&' => out.push_str("%26"),
            '=' => out.push_str("%3D"),
            '#' => out.push_str("%23"),
            '?' => out.push_str("%3F"),
            _ => out.push(ch),
        }
    }
    out
}

/// Convert snake_case to Title Case for humans.
fn humanise(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let mut next_upper = true;
    for ch in s.chars() {
        if ch == '_' {
            out.push(' ');
            next_upper = true;
        } else if next_upper {
            out.push(ch.to_ascii_uppercase());
            next_upper = false;
        } else {
            out.push(ch);
        }
    }
    out
}

/// Humanise an enum-like `String` value for display. `in_progress` →
/// `"In progress"` (sentence case, not Title Case — an enum value in
/// a dropdown reads better as a label than as a book title). Raw
/// value stays untouched for round-trip via form POST.
fn humanise_enum_value(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let mut first = true;
    for ch in s.chars() {
        if ch == '_' {
            out.push(' ');
        } else if first {
            out.push(ch.to_ascii_uppercase());
            first = false;
        } else {
            out.push(ch.to_ascii_lowercase());
        }
    }
    out
}

/// Naive pluralise for filter placeholders. `"patient"` → `"patients"`,
/// `"status"` → `"statuses"`, `"category"` → `"categories"`. Good
/// enough for our display labels; the macro's plural for model names
/// is a separate codepath.
fn pluralise_label(s: &str) -> String {
    let lower = s.to_lowercase();
    if lower.ends_with('s')
        || lower.ends_with('x')
        || lower.ends_with("ch")
        || lower.ends_with("sh")
    {
        format!("{lower}es")
    } else if lower.ends_with('y')
        && !lower.ends_with("ay")
        && !lower.ends_with("ey")
        && !lower.ends_with("iy")
        && !lower.ends_with("oy")
        && !lower.ends_with("uy")
    {
        format!("{}ies", &lower[..lower.len() - 1])
    } else {
        format!("{lower}s")
    }
}

/// Default column cap for the list-page visible set. Above this the
/// table starts to feel wide; users opt into more via the Columns
/// control. Caps apply after the rule-set + fill step below.
const DEFAULT_VISIBLE_COLUMNS: usize = 5;

/// Name-like columns that rule 3 in [`is_primary_column`] treats as
/// the "first match" name field. A single model may have several
/// of these (e.g. both `full_name` and `email`); only the one that
/// appears first in declaration order gets primary status, handled
/// by the caller since the decision needs cross-field context.
const NAME_LIKE_FIELDS: &[&str] = &["name", "full_name", "title", "email"];

/// Field-local rules for primary-column membership. Returns `true`
/// if the column qualifies based on properties of the field alone;
/// rule 3 (first name-like match) requires model-wide context and is
/// applied in [`default_list_columns`].
///
/// Rules applied here (spec order, excluding rule 3):
///   1. `name == "id"`              → primary
///   2. model's `primary_display_field` attribute matches — RustIO
///      has no such attribute today; placeholder for a future macro
///      addition. Always `false` in this pass.
///   4. `relation.is_some()` AND    → primary
///      name ends with `_id`
///   5. `Bool` type AND             → primary
///      name starts with `is_`
///   6. name ∈ {status, state, priority} → primary
///   7. otherwise                   → not primary
///
/// Rule 3 lives in [`default_list_columns`] because "first match on
/// the model" can't be decided from a single `&AdminField`.
pub(crate) fn is_primary_column(f: &AdminField) -> bool {
    // Rule 1.
    if f.name == "id" {
        return true;
    }
    // Rule 2 intentionally omitted — no such attribute yet.
    // Rule 4.
    if f.relation.is_some() && f.name.ends_with("_id") {
        return true;
    }
    // Rule 5.
    if matches!(f.ty, FieldType::Bool) && f.name.starts_with("is_") {
        return true;
    }
    // Rule 6.
    if matches!(f.name, "status" | "state" | "priority") {
        return true;
    }
    // Rule 7.
    false
}

/// Compute the default set of visible columns for a model's list
/// page. Generic across every rustio project — relies only on
/// [`AdminField`] shape (type, name, relation). Algorithm:
///
/// 1. Collect every field that matches [`is_primary_column`].
/// 2. Apply rule 3: if any field name appears in [`NAME_LIKE_FIELDS`],
///    include only the first-in-declaration-order match.
/// 3. Cap at [`DEFAULT_VISIBLE_COLUMNS`] (5), keeping declaration
///    order.
///
/// If fewer than 5 fields match, the return value has fewer than 5
/// entries — no padding. Users can reveal hidden columns via the
/// Columns control.
///
/// Output preserves declaration order, which is how the list
/// renderer expects it.
pub(crate) fn default_list_columns<T: AdminModel>() -> Vec<&'static str> {
    let fields = T::FIELDS;
    let mut picked: Vec<&'static str> = Vec::with_capacity(DEFAULT_VISIBLE_COLUMNS);

    // Rule-based picks, with rule 3 applied as "first name-like
    // match wins". Scan in declaration order; a later name-like
    // field can't override an earlier one. Cap at
    // DEFAULT_VISIBLE_COLUMNS; no fill step.
    let mut name_rule_used = false;
    for f in fields {
        if picked.len() >= DEFAULT_VISIBLE_COLUMNS {
            break;
        }
        let hits_name_rule = !name_rule_used && NAME_LIKE_FIELDS.contains(&f.name);
        if is_primary_column(f) || hits_name_rule {
            picked.push(f.name);
            if hits_name_rule {
                name_rule_used = true;
            }
        }
    }

    picked
}

/// Drop a trailing ` Id` from a humanised field name when the column
/// is declared as a FK relation. `"Patient Id"` → `"Patient"` so the
/// edit form reads naturally. The underlying form field name stays
/// the raw column (`patient_id`) so POST still round-trips.
fn field_label(f: &AdminField) -> String {
    let base = humanise(f.name);
    if f.relation.is_some() {
        base.strip_suffix(" Id").map(str::to_string).unwrap_or(base)
    } else {
        base
    }
}

/// Render a metadata block for the edit page: id + immutable
/// (non-editable) field values.
fn render_meta<T: AdminModel>(id: i64, item: &T) -> String {
    let mut items = vec![format!(
        r#"<div class="rio-meta-item">
<span class="rio-meta-label">ID</span>
<span class="rio-meta-value">#{id}</span>
</div>"#,
    )];

    for f in T::FIELDS.iter() {
        if f.editable || f.name == "id" {
            continue;
        }
        let value = item.field_display(f.name).unwrap_or_default();
        let shown = if value.is_empty() {
            "—".to_string()
        } else {
            value
        };
        items.push(format!(
            r#"<div class="rio-meta-item">
<span class="rio-meta-label">{label}</span>
<span class="rio-meta-value">{value}</span>
</div>"#,
            label = escape_html(&humanise(f.name)),
            value = escape_html(&shown),
        ));
    }

    format!(r#"<div class="rio-meta">{}</div>"#, items.join(""))
}

/// Render the raw input widget for an admin field. Signature preserved
/// from earlier releases because tests and downstream code depend on
/// the exact output shape (presence/absence of `required`, the
/// `type="datetime-local"` hook, `value=""` for None).
fn render_field<T: AdminModel>(
    f: &AdminField,
    item: Option<&T>,
    placeholder: Option<&str>,
    form_options: &FormRelationOptions,
) -> String {
    let current = item
        .and_then(|i| i.field_display(f.name))
        .unwrap_or_default();
    let n = escape_html(f.name);
    let v = escape_html(&current);

    let required = if !f.nullable && !matches!(f.ty, FieldType::Bool) {
        " required"
    } else {
        ""
    };

    let placeholder_attr = match placeholder {
        Some(p) if !p.is_empty() => format!(r#" placeholder="{}""#, escape_html(p)),
        _ => String::new(),
    };

    // FK dropdown — preferred presentation for i32/i64 fields that
    // carry a `belongs_to` AND have a pre-fetched option list (see
    // [`fetch_form_relation_options`]). Falls through to the raw
    // number input when no options are present (no relation, no
    // `display_field`, or row count over the cap).
    if matches!(f.ty, FieldType::I32 | FieldType::I64) {
        if let Some(options) = form_options.get(f.name) {
            let none_opt = if f.nullable {
                r#"<option value="">— none —</option>"#
            } else {
                r#"<option value="" disabled selected>Select…</option>"#
            };
            let options_html: String = options
                .iter()
                .map(|(id, label)| {
                    let selected = if current == id.to_string() {
                        " selected"
                    } else {
                        ""
                    };
                    format!(
                        r#"<option value="{id}"{selected}>{label}</option>"#,
                        id = id,
                        selected = selected,
                        label = escape_html(label),
                    )
                })
                .collect();
            // Suppress the default-selected "Select…" when editing a
            // row whose FK already has a value — the matching option
            // already carries `selected`.
            let none_opt = if !current.is_empty() && !f.nullable {
                r#"<option value="" disabled>Select…</option>"#
            } else {
                none_opt
            };
            return format!(
                r#"<select class="rio-input rio-select" id="_{n}" name="{n}"{required}>{none}{opts}</select>"#,
                n = n,
                required = required,
                none = none_opt,
                opts = options_html,
            );
        }
    }

    match f.ty {
        FieldType::Bool => format!(
            r#"<input class="rio-checkbox" id="_{n}" type="checkbox" name="{n}" {checked}>"#,
            checked = if current == "true" { "checked" } else { "" },
        ),
        FieldType::I32 | FieldType::I64 => {
            format!(
                r#"<input class="rio-input" id="_{n}" type="number" name="{n}" value="{v}"{required}{placeholder_attr}>"#
            )
        }
        FieldType::String => {
            format!(
                r#"<input class="rio-input" id="_{n}" type="text" name="{n}" value="{v}"{required}{placeholder_attr}>"#
            )
        }
        FieldType::DateTime => {
            format!(
                r#"<input class="rio-input" id="_{n}" type="datetime-local" name="{n}" value="{v}"{required}{placeholder_attr}>"#
            )
        }
    }
}

// ---------------------------------------------------------------------------
// Delete confirmation page
// ---------------------------------------------------------------------------

fn delete_confirmation_response<T: AdminModel>(shell: Shell<'_>, id: i64, item: &T) -> Response {
    let singular = T::singular_name();
    let plural = T::DISPLAY_NAME;
    let admin_name = T::ADMIN_NAME;

    // Pick a display value: the first editable String field, or fall
    // back to the id. Gives the confirmation page some context beyond
    // a bare number.
    let summary = T::FIELDS
        .iter()
        .find(|f| f.editable && matches!(f.ty, FieldType::String))
        .and_then(|f| item.field_display(f.name))
        .filter(|s| !s.is_empty())
        .unwrap_or_else(|| format!("#{id}"));

    let csrf_hidden = csrf_input(shell.csrf);

    // Context-aware GDPR / PII banner. Fires when this record has at
    // least one field the intelligence layer classifies as sensitive
    // under the project's `rustio.context.json`.
    let ctx = intelligence::context_global();
    let has_pii = T::FIELDS
        .iter()
        .any(|f| intelligence::field_ui_metadata(f, ctx).sensitive);
    let pii_banner = if has_pii {
        let note = if ctx.is_some_and(|c| c.requires_gdpr()) {
            "This record contains personal data (GDPR). Deletion is typically irreversible — verify you have the right to erase."
        } else {
            "This record contains fields flagged as personal data. Review before proceeding."
        };
        format!(
            r#"<div class="rio-alert rio-alert-error">{icon}<div><strong>Sensitive data.</strong> {note}</div></div>"#,
            icon = icon_shield_alert(),
            note = escape_html(note),
        )
    } else {
        String::new()
    };

    let body = format!(
        r#"<div class="rio-card">
<div class="rio-card-body">
{pii_banner}
<div class="rio-alert rio-alert-warn">
{warn}
<div>
<strong>This action cannot be undone.</strong>
Deleting this record removes it permanently. Rows that reference it via a foreign key with <code>ON DELETE CASCADE</code> will be deleted too.
</div>
</div>
<p>You are about to delete <strong>{singular}</strong>:</p>
<div class="rio-meta">
<div class="rio-meta-item">
<span class="rio-meta-label">ID</span>
<span class="rio-meta-value">#{id}</span>
</div>
<div class="rio-meta-item">
<span class="rio-meta-label">Summary</span>
<span class="rio-meta-value">{summary}</span>
</div>
</div>
</div>
<div class="rio-form-footer">
<a class="rio-btn rio-btn-ghost" href="/admin/{name}">{back}<span>Back to {plural_lower}</span></a>
<div class="rio-footer-actions">
<a class="rio-btn" href="/admin/{name}/{id}/edit">Cancel</a>
<form class="rio-inline-form" method="post" action="/admin/{name}/{id}/delete">
{csrf}
<button class="rio-btn rio-btn-danger" type="submit">{trash}<span>Delete {singular}</span></button>
</form>
</div>
</div>
</div>"#,
        warn = icon_triangle_alert(),
        singular = escape_html(singular),
        id = id,
        summary = escape_html(&summary),
        name = escape_html(admin_name),
        back = icon_arrow_left(),
        plural_lower = escape_html(&plural.to_lowercase()),
        csrf = csrf_hidden,
        trash = icon_trash(),
    );

    let plural_href = format!("/admin/{admin_name}");
    let crumbs: &[Crumb<'_>] = &[
        ("Admin", Some("/admin")),
        (plural, Some(&plural_href)),
        ("Delete", None),
    ];

    render_shell_page(
        &shell,
        200,
        &format!("Delete {singular}"),
        &format!("Delete {singular}?"),
        Some("Confirm you want to remove this record."),
        crumbs,
        "",
        &body,
    )
}

/// Intermediate confirmation page for a bulk delete. Shows the list of
/// records that will be deleted and posts back to the same URL with
/// `_confirm=yes` when the operator commits. Mirrors Django's "Are
/// you sure?" step.
fn bulk_delete_confirmation_response<T: AdminModel>(
    shell: &Shell<'_>,
    items: &[(i64, String)],
) -> Response {
    let singular = T::singular_name();
    let plural = T::DISPLAY_NAME;
    let admin_name = T::ADMIN_NAME;
    let csrf_hidden = csrf_input(shell.csrf);

    let count = items.len();
    let count_label = if count == 1 {
        format!("1 {}", singular.to_lowercase())
    } else {
        format!("{count} {}", plural.to_lowercase())
    };

    // Hidden `_selected` carries the IDs forward. Each row shows the
    // id + the primary string value so the operator can verify.
    let selected_csv: String = items
        .iter()
        .map(|(id, _)| id.to_string())
        .collect::<Vec<_>>()
        .join(",");
    let rows: String = items
        .iter()
        .map(|(id, primary)| {
            let label = if primary.is_empty() {
                format!("#{id}")
            } else {
                format!("#{id} · {primary}")
            };
            format!(
                r#"<li class="rio-bulk-item">{label}</li>"#,
                label = escape_html(&label),
            )
        })
        .collect();

    let body = format!(
        r#"<div class="rio-card">
<div class="rio-card-body">
<div class="rio-alert rio-alert-warn">
{warn}
<div>
<strong>This action cannot be undone.</strong>
You are about to delete <strong>{count_label}</strong>. Each record removed here is logged individually in <a href="/admin/actions">Recent actions</a>.
</div>
</div>
<p>Review the list, then confirm:</p>
<ul class="rio-bulk-list">{rows}</ul>
</div>
<form method="post" action="/admin/{name}/bulk_action" class="rio-form-footer">
{csrf}
<input type="hidden" name="action" value="delete">
<input type="hidden" name="_selected" value="{selected}">
<input type="hidden" name="_confirm" value="yes">
<a class="rio-btn rio-btn-ghost" href="/admin/{name}">{back}<span>Cancel</span></a>
<div class="rio-footer-actions">
<button class="rio-btn rio-btn-danger" type="submit">{trash}<span>Yes, delete {count_label}</span></button>
</div>
</form>
</div>"#,
        warn = icon_triangle_alert(),
        count_label = escape_html(&count_label),
        rows = rows,
        name = escape_html(admin_name),
        csrf = csrf_hidden,
        selected = escape_html(&selected_csv),
        back = icon_arrow_left(),
        trash = icon_trash(),
    );

    let plural_href = format!("/admin/{admin_name}");
    let crumbs: &[Crumb<'_>] = &[
        ("Admin", Some("/admin")),
        (plural, Some(&plural_href)),
        ("Delete selected", None),
    ];

    render_shell_page(
        shell,
        200,
        &format!("Delete selected {}", plural.to_lowercase()),
        &format!("Delete selected {}?", plural.to_lowercase()),
        Some("Confirm you want to remove these records."),
        crumbs,
        "",
        &body,
    )
}

// ---------------------------------------------------------------------------
// Styled 404 + 500 (rendered inside the admin shell)
// ---------------------------------------------------------------------------

fn new_request_id() -> String {
    use rand::RngCore as _;
    let mut buf = [0u8; 6];
    rand::rngs::OsRng.fill_bytes(&mut buf);
    let mut s = String::with_capacity(12);
    for b in buf {
        s.push_str(&format!("{b:02x}"));
    }
    s
}

/// Minimal shell built without a live `Context`. Used by the admin
/// error middleware when the request has already been consumed.
fn error_shell<'a>(
    entries: &'a [AdminEntry],
    email: Option<&'a str>,
    csrf: Option<&'a str>,
) -> Shell<'a> {
    Shell {
        entries,
        active: None,
        user_email: email,
        csrf,
    }
}

/// 404 page rendered via `minijinja` against `auth/not_found.html`.
/// Called by the admin error middleware when any `/admin/*` handler
/// returns `Err(Error::NotFound)`. Unused callbacks (`entries`,
/// `email`) are kept in the signature to match the existing call
/// site — stage 5 cleanup retires the argument list.
fn admin_not_found_response(
    _entries: &[AdminEntry],
    _email: Option<&str>,
    csrf: Option<&str>,
) -> Response {
    let design = design::Design::global();
    let env = crate::admin::templating::env();
    let body = match env.get_template("auth/not_found.html").and_then(|tmpl| {
        tmpl.render(minijinja::context! {
            design => minijinja::context! {
                project_name => design.project_name.as_str(),
                logo_initial => design.logo_initial.as_str(),
            },
            csrf_token => csrf.unwrap_or(""),
        })
    }) {
        Ok(html) => html,
        Err(err) => {
            eprintln!("admin not-found template render failed: {err}");
            format!(
                "<!doctype html><html><head><meta charset=\"utf-8\"><title>404 Not Found · {p}</title></head><body style=\"font-family:system-ui;max-width:28rem;margin:4rem auto;padding:0 1rem;text-align:center\"><p>404 Not Found</p><h1>We couldn't find that page.</h1><p><a href=\"/admin\">Back to dashboard</a></p></body></html>",
                p = escape_html(&design.project_name),
            )
        }
    };
    let resp = hyper::Response::builder()
        .status(404)
        .header("content-type", "text/html; charset=utf-8")
        .body(Full::new(Bytes::from(body)))
        .expect("valid response");
    with_admin_headers(resp)
}

fn admin_server_error_response(
    entries: &[AdminEntry],
    email: Option<&str>,
    csrf: Option<&str>,
    request_id: &str,
) -> Response {
    let shell = error_shell(entries, email, csrf);
    let when = Utc::now().format("%Y-%m-%d %H:%M UTC").to_string();
    let body = format!(
        r#"<div class="rio-card">
<div class="rio-card-body">
<div class="rio-alert rio-alert-error">
{icon}
<div>
<strong>Something went wrong.</strong>
The admin could not complete your request. The detail has been logged server-side; the summary below is what to share when reporting.
</div>
</div>
<div class="rio-meta">
<div class="rio-meta-item">
<span class="rio-meta-label">Request ID</span>
<span class="rio-meta-value"><code>{rid}</code></span>
</div>
<div class="rio-meta-item">
<span class="rio-meta-label">Timestamp</span>
<span class="rio-meta-value">{when}</span>
</div>
</div>
<div class="rio-error-actions">
<a class="rio-btn" href="/admin">{back}<span>Back to dashboard</span></a>
</div>
</div>
</div>"#,
        icon = icon_triangle_alert(),
        rid = escape_html(request_id),
        when = escape_html(&when),
        back = icon_arrow_left(),
    );
    let crumbs: &[Crumb<'_>] = &[("Admin", Some("/admin")), ("Server error", None)];
    render_shell_page(
        &shell,
        500,
        "500 Server Error",
        "500 · Server error",
        Some("The admin could not complete your request."),
        crumbs,
        "",
        &body,
    )
}

// ---------------------------------------------------------------------------
// Shared admin-engine model handlers
// ---------------------------------------------------------------------------
//
// `/admin/:model` and `/admin-new/:model` both delegate here so the
// engine has exactly one implementation. Routing is the only thing
// that differs between the two surfaces. After parity is confirmed
// the alias `/admin-new/:model` will be removed; this file stays
// untouched at that point.

async fn admin_model_index_get(
    db: &Db,
    registry: &crate::admin::admin_form_bridge::AdminRegistry,
    legacy_entries: &[AdminEntry],
    req: Request,
    params: crate::router::Params,
) -> Result<Response, Error> {
    if let Err(resp) = admin_guard(req.ctx()) {
        return Ok(resp);
    }
    let model_slug = params.get("model").unwrap_or("").to_string();

    // Resolve the model: new registry first, then fall back to
    // a legacy `AdminEntry` (wrapped in a `LegacyEntryModel` adapter
    // so the template-based renderer doesn't care which source it
    // came from). If neither source knows the slug, 404.
    enum ResolvedModel {
        New(Box<dyn crate::admin::admin_form_bridge::AdminUiModel>),
        Legacy(crate::admin::layout::LegacyEntryModel),
    }
    let resolved = if let Some(model) = registry.get(&model_slug) {
        ResolvedModel::New(model)
    } else if let Some(entry) = legacy_entries
        .iter()
        .find(|e| !e.core && e.admin_name == model_slug)
    {
        ResolvedModel::Legacy(crate::admin::layout::LegacyEntryModel::new(entry))
    } else {
        return Err(Error::NotFound);
    };
    let q_map = req.query().into_map();
    let id = q_map.get("id").filter(|s| !s.is_empty()).cloned();
    let query = q_map
        .get("q")
        .map(|s| s.trim())
        .filter(|s| !s.is_empty())
        .map(String::from);
    let page = q_map
        .get("page")
        .and_then(|p| p.parse::<i64>().ok())
        .filter(|p| *p > 0)
        .unwrap_or(1);
    let sort = q_map.get("sort").filter(|s| !s.is_empty()).cloned();
    let dir = q_map.get("dir").filter(|s| !s.is_empty()).cloned();
    // Phase 7 — list-page layout switcher. Read here and exclude from the
    // `filters` map so it isn't mistaken for a column filter.
    let layout = q_map.get("layout").filter(|s| !s.is_empty()).cloned();
    let filters: std::collections::HashMap<String, String> = q_map
        .iter()
        .filter(|(k, v)| {
            !v.is_empty()
                && k.as_str() != "q"
                && k.as_str() != "page"
                && k.as_str() != "id"
                && k.as_str() != "sort"
                && k.as_str() != "dir"
                && k.as_str() != "layout"
                && k.as_str() != "advanced"
        })
        .map(|(k, v)| (k.clone(), v.clone()))
        .collect();
    let _ = q_map
        .get("advanced")
        .map(|s| !s.is_empty())
        .unwrap_or(false);
    // Stage 4e: route to the template-based list renderer. The `id`
    // query param (drawer-edit in the legacy flow) is intentionally
    // ignored here; stage 4f adds dedicated /admin/:model/:id/edit
    // routes as the replacement.
    let _ = id;
    let identity = crate::auth::identity(req.ctx()).cloned();
    let csrf = ctx_csrf(req.ctx()).map(str::to_string);
    let html = match &resolved {
        ResolvedModel::New(model) => {
            crate::admin::layout::list_render(
                std::path::Path::new("."),
                db,
                registry,
                legacy_entries,
                &**model,
                None,
                query.as_deref(),
                page,
                &filters,
                sort.as_deref(),
                dir.as_deref(),
                layout.as_deref(),
                identity.as_ref(),
                csrf.as_deref(),
            )
            .await
        }
        ResolvedModel::Legacy(model) => {
            let source = model.source_entry().clone();
            crate::admin::layout::list_render(
                std::path::Path::new("."),
                db,
                registry,
                legacy_entries,
                model,
                Some(&source),
                query.as_deref(),
                page,
                &filters,
                sort.as_deref(),
                dir.as_deref(),
                layout.as_deref(),
                identity.as_ref(),
                csrf.as_deref(),
            )
            .await
        }
    };
    Ok(with_admin_headers(crate::http::html(html)))
}

/// GET handler for both `/admin/:model/new` and
/// `/admin/:model/:id/edit`. Resolves the slug through the same
/// new-registry → legacy-entries fallback that
/// `admin_model_index_get` uses, then delegates to
/// `layout::form_render`. No mutation — stage 4f-b wires POST.
async fn admin_model_form_get(
    db: &Db,
    registry: &crate::admin::admin_form_bridge::AdminRegistry,
    legacy_entries: &[AdminEntry],
    req: Request,
    params: crate::router::Params,
    editing_id: Option<&str>,
) -> Result<Response, Error> {
    if let Err(resp) = admin_guard(req.ctx()) {
        return Ok(resp);
    }
    let model_slug = params.get("model").unwrap_or("").to_string();

    enum ResolvedModel {
        New(Box<dyn crate::admin::admin_form_bridge::AdminUiModel>),
        Legacy(crate::admin::layout::LegacyEntryModel),
    }
    let resolved = if let Some(model) = registry.get(&model_slug) {
        ResolvedModel::New(model)
    } else if let Some(entry) = legacy_entries
        .iter()
        .find(|e| !e.core && e.admin_name == model_slug)
    {
        ResolvedModel::Legacy(crate::admin::layout::LegacyEntryModel::new(entry))
    } else {
        return Err(Error::NotFound);
    };

    let identity = crate::auth::identity(req.ctx()).cloned();
    let csrf = ctx_csrf(req.ctx()).map(str::to_string);
    let html = match &resolved {
        ResolvedModel::New(model) => {
            crate::admin::layout::form_render(
                db,
                registry,
                legacy_entries,
                &**model,
                None,
                editing_id,
                identity.as_ref(),
                csrf.as_deref(),
                None,
            )
            .await
        }
        ResolvedModel::Legacy(model) => {
            let source = model.source_entry().clone();
            crate::admin::layout::form_render(
                db,
                registry,
                legacy_entries,
                model,
                Some(&source),
                editing_id,
                identity.as_ref(),
                csrf.as_deref(),
                None,
            )
            .await
        }
    };
    Ok(with_admin_headers(crate::http::html(html)))
}

// 0.10 stage 4f-b: POST handlers for the new form routes.
//
// Each handler resolves the `:model` slug through the same
// new-registry → legacy-entries fallback the GET handlers use,
// validates CSRF against the session, then mutates via
// `admin::persistence`. Success → 303 redirect to the list page
// (Post/Redirect/Get). Failure → re-render the form with an error
// banner (no input preservation yet — see TODO in `form_render`).

fn resolve_form_model(
    registry: &crate::admin::admin_form_bridge::AdminRegistry,
    legacy_entries: &[AdminEntry],
    slug: &str,
) -> Result<FormResolvedModel, Error> {
    if let Some(model) = registry.get(slug) {
        return Ok(FormResolvedModel::New(model));
    }
    if let Some(entry) = legacy_entries
        .iter()
        .find(|e| !e.core && e.admin_name == slug)
    {
        return Ok(FormResolvedModel::Legacy(
            crate::admin::layout::LegacyEntryModel::new(entry),
        ));
    }
    Err(Error::NotFound)
}

enum FormResolvedModel {
    New(Box<dyn crate::admin::admin_form_bridge::AdminUiModel>),
    Legacy(crate::admin::layout::LegacyEntryModel),
}

impl FormResolvedModel {
    fn as_ui_model(&self) -> &dyn crate::admin::admin_form_bridge::AdminUiModel {
        match self {
            FormResolvedModel::New(m) => &**m,
            FormResolvedModel::Legacy(m) => m,
        }
    }

    /// `Some(entry)` when the model came from a legacy registration,
    /// so the form layer can populate FK `<select>` options from the
    /// entry's relation metadata. `None` for new-engine models —
    /// they pre-populate `AdminUiField.options` at registration time.
    fn legacy_source(&self) -> Option<&AdminEntry> {
        match self {
            FormResolvedModel::New(_) => None,
            FormResolvedModel::Legacy(m) => Some(m.source_entry()),
        }
    }
}

/// Build a `column → value` map from a submitted form body, scoped
/// to the model's declared fields. The PK is excluded so a client
/// can't overwrite it. Readonly fields are excluded too — they
/// display on the edit form but must not be accepted as inputs.
fn build_mutation_data(
    model: &dyn crate::admin::admin_form_bridge::AdminUiModel,
    form: &FormData,
) -> std::collections::HashMap<String, String> {
    let pk = model.primary_key();
    let mut out = std::collections::HashMap::new();
    for field in model.fields() {
        if field.name == pk || field.readonly {
            continue;
        }
        let value = form.get(field.name).unwrap_or("");
        out.insert(field.name.to_string(), value.to_string());
    }
    out
}

async fn admin_model_create_post(
    db: &Db,
    registry: &crate::admin::admin_form_bridge::AdminRegistry,
    legacy_entries: &[AdminEntry],
    req: Request,
    params: crate::router::Params,
) -> Result<Response, Error> {
    if let Err(resp) = admin_guard(req.ctx()) {
        return Ok(resp);
    }
    let model_slug = params.get("model").unwrap_or("").to_string();
    let resolved = resolve_form_model(registry, legacy_entries, &model_slug)?;

    let (_, body, ctx) = req.into_parts();
    let form = read_form_from_parts(body).await?;
    require_csrf(&ctx, &form)?;

    let data = build_mutation_data(resolved.as_ui_model(), &form);
    match crate::admin::persistence::insert_record(db, resolved.as_ui_model().table_name(), &data)
        .await
    {
        Ok(_) => Ok(with_admin_headers(redirect(&format!(
            "/admin/{model_slug}"
        )))),
        Err(e) => {
            let identity = crate::auth::identity(&ctx).cloned();
            let csrf = ctx_csrf(&ctx).map(str::to_string);
            let error_msg = format!("Could not create: {e}");
            let source = resolved.legacy_source().cloned();
            let html = crate::admin::layout::form_render(
                db,
                registry,
                legacy_entries,
                resolved.as_ui_model(),
                source.as_ref(),
                None,
                identity.as_ref(),
                csrf.as_deref(),
                Some(&error_msg),
            )
            .await;
            Ok(with_admin_headers(crate::http::html(html)))
        }
    }
}

