/// Phase 8 — `POST /admin/:model/layout`. Persist the chosen list layout as
/// the model's default in `<model>.view.json`. Mirrors the delete action's
/// wiring exactly: `admin_guard` (admin/edit gate) → resolve model → read
/// form → **CSRF verify** → validate the `layout` value → write via
/// [`save_layout_default`](crate::admin::layout::save_layout_default)
/// (which reuses `ViewSpec::write_to`'s atomic temp+rename) → redirect to a
/// **sanitized** `_return` path.
/// Validate a post-action redirect target for the language switcher. Unlike
/// `sanitize_return` (scoped to one model's pages), this allows any admin page
/// — the user could set their language from anywhere — while still rejecting
/// open-redirects / traversal. Falls back to `/admin`.
fn safe_admin_return(raw: &str) -> String {
    let ok = raw.starts_with("/admin")
        && !raw.contains("..")
        && !raw.contains('\\')
        && !raw.contains("//");
    if ok {
        raw.to_string()
    } else {
        "/admin".to_string()
    }
}

/// i18n L4a — `POST /admin/language`. Save the signed-in user's UI language
/// preference. **Per-user; never mutates a ViewSpec or its default_language.**
/// Mirrors `admin_model_layout_post`: `admin_guard` → read form → CSRF verify →
/// validate `lang` (a known code, or empty = clear) → persist → redirect back.
async fn admin_language_post(req: Request, db: &Db) -> Result<Response, Error> {
    if let Err(resp) = admin_guard(req.ctx()) {
        return Ok(resp);
    }
    let (_, body, ctx) = req.into_parts();
    let form = read_form_from_parts(body).await?;
    require_csrf(&ctx, &form)?;

    let lang = form.get("lang").unwrap_or("").trim().to_string();
    // A known language, or empty (clears the preference → revert to the view's
    // default_language). Anything else is rejected — never stored.
    if !lang.is_empty() && !crate::admin::layout::is_known_language(&lang) {
        return Err(Error::BadRequest("unknown language".into()));
    }
    let identity = crate::auth::identity(&ctx).ok_or(Error::Unauthorized)?;
    crate::auth::user::set_preferred_language(db, identity.user_id, &lang).await?;

    let target = safe_admin_return(form.get("_return").unwrap_or(""));
    Ok(with_admin_headers(redirect(&target)))
}

async fn admin_model_layout_post(
    registry: &crate::admin::admin_form_bridge::AdminRegistry,
    legacy_entries: &[AdminEntry],
    req: Request,
    params: crate::router::Params,
) -> Result<Response, Error> {
    // Edit/write gate (defense in depth — the UI also hides the control for
    // users without edit). `admin_guard` requires an admin identity.
    if let Err(resp) = admin_guard(req.ctx()) {
        return Ok(resp);
    }
    let model_slug = params.get("model").unwrap_or("").to_string();
    let resolved = resolve_form_model(registry, legacy_entries, &model_slug)?;

    let (_, body, ctx) = req.into_parts();
    let form = read_form_from_parts(body).await?;
    require_csrf(&ctx, &form)?;

    // Validate the requested layout against the four known values.
    let layout = crate::admin::layout::parse_layout_strict(form.get("layout"))
        .ok_or_else(|| Error::BadRequest("invalid layout".into()))?;

    let ui = resolved.as_ui_model();
    let schema_model = crate::admin::layout::schema_model_from_ui(ui.model_name(), &ui.fields());
    crate::admin::layout::save_layout_default(
        std::path::Path::new("."),
        ui.model_name(),
        &schema_model,
        layout,
    )?;

    // Redirect back to the list (no `?layout=`, so the new saved default
    // applies), preserving filters via the strictly-validated `_return`.
    let target =
        crate::admin::layout::sanitize_return(&model_slug, form.get("_return").unwrap_or(""));
    Ok(with_admin_headers(redirect(&target)))
}

/// Phase 9a — `GET /admin/:model/view`. Render the composition editor (the
/// field-role table). Edit-gated via `admin_guard`.
async fn admin_model_view_get(
    db: &Db,
    registry: &crate::admin::admin_form_bridge::AdminRegistry,
    legacy_entries: &[AdminEntry],
    req: Request,
    params: crate::router::Params,
) -> Result<Response, Error> {
    if let Err(resp) = admin_guard(req.ctx()) {
        return Ok(resp);
    }
    let model_slug = params.get("model").unwrap_or("").to_string();
    let resolved = resolve_form_model(registry, legacy_entries, &model_slug)?;
    let identity = crate::auth::identity(req.ctx()).cloned();
    let csrf = ctx_csrf(req.ctx()).map(str::to_string);
    let return_to = format!("/admin/{model_slug}");
    // i18n L3 — `?lang=` selects the editing language (GET reload, no save).
    let editing_lang = req.query().get("lang").unwrap_or("").to_string();

    let html = crate::admin::layout::view_editor_render(
        std::path::Path::new("."),
        db,
        registry,
        legacy_entries,
        resolved.as_ui_model(),
        identity.as_ref(),
        csrf.as_deref(),
        &return_to,
        None,
        &editing_lang,
    )
    .await;
    Ok(with_admin_headers(crate::http::html(html)))
}

/// Phase 9a — `POST /admin/:model/view`. Save the edited field roles.
/// Mirrors `admin_model_layout_post`: `admin_guard` → resolve model → read
/// form → **CSRF verify** → build the candidate from `role[<source>]`
/// (preserving order / merge / filterable) → **validate** → write via
/// `save_view_spec` → redirect. An unparseable role value or a failed
/// `validate()` re-renders the editor with the error and **writes nothing**.
async fn admin_model_view_post(
    db: &Db,
    registry: &crate::admin::admin_form_bridge::AdminRegistry,
    legacy_entries: &[AdminEntry],
    req: Request,
    params: crate::router::Params,
) -> Result<Response, Error> {
    if let Err(resp) = admin_guard(req.ctx()) {
        return Ok(resp);
    }
    let model_slug = params.get("model").unwrap_or("").to_string();
    let resolved = resolve_form_model(registry, legacy_entries, &model_slug)?;

    let (_, body, ctx) = req.into_parts();
    let form = read_form_from_parts(body).await?;
    require_csrf(&ctx, &form)?;

    let identity = crate::auth::identity(&ctx).cloned();
    let csrf = ctx_csrf(&ctx).map(str::to_string);
    let return_to =
        crate::admin::layout::sanitize_return(&model_slug, form.get("_return").unwrap_or(""));

    let ui = resolved.as_ui_model();
    let ui_fields = ui.fields();
    let schema_model = crate::admin::layout::schema_model_from_ui(ui.model_name(), &ui_fields);
    let spec = crate::admin::layout::resolve_view(
        std::path::Path::new("."),
        ui.model_name(),
        &schema_model,
    );

    // i18n L3 — keep the editing language across an error re-render so the
    // label inputs stay in the language the developer was editing.
    let editing_lang = form.get("editing_lang").unwrap_or("").to_string();

    // Re-render the editor with an error, writing nothing.
    macro_rules! reject {
        ($msg:expr) => {{
            let html = crate::admin::layout::view_editor_render(
                std::path::Path::new("."),
                db,
                registry,
                legacy_entries,
                ui,
                identity.as_ref(),
                csrf.as_deref(),
                &return_to,
                Some($msg),
                &editing_lang,
            )
            .await;
            return Ok(with_admin_headers(crate::http::html(html)));
        }};
    }

    // Build candidate from the submitted roles + order (merge/filterable
    // preserved). An unknown role value rejects — never a silent fallback.
    let candidate = match crate::admin::layout::build_edited_spec(&spec, &form) {
        Ok(c) => c,
        Err(msg) => reject!(&msg),
    };
    // Validate before writing (load-bearing for 9c/9d; role edits can't
    // trip it today, but the guard is wired in now).
    if let Err(e) = candidate.validate() {
        reject!(&e.to_string());
    }
    crate::admin::layout::save_view_spec(std::path::Path::new("."), ui.model_name(), &candidate)?;
    Ok(with_admin_headers(redirect(&return_to)))
}

// ---------------------------------------------------------------------------
// Admin guard + login/forbidden auth pages
// ---------------------------------------------------------------------------

#[allow(clippy::result_large_err)]
fn admin_guard(ctx: &crate::context::Context) -> Result<(), Response> {
    match crate::auth::require_admin(ctx) {
        Ok(_) => Ok(()),
        Err(Error::Unauthorized) => Err(login_page(401, None, None)),
        Err(Error::Forbidden) => Err(forbidden_page(ctx_csrf(ctx))),
        Err(other) => Err(other.into_response()),
    }
}

/// Render the login page. Status 401 on a pure auth-gate hit; 400 on
/// missing fields; 403 on inactive account; 429 on rate-limit trip.
///
/// Rendered via `minijinja` against `auth/login.html` (bundled in
/// `rustio-core/assets/templates/`; user projects can override by
/// placing a same-named file under their own `templates/auth/`). If
/// the template fails to render for any reason — parse error, missing
/// include, IO error on an override — the renderer falls back to a
/// minimal inline HTML shell that still serves the same form. The
/// server never crashes on a bad template.
fn login_page(status: u16, email: Option<&str>, error: Option<&str>) -> Response {
    let design = design::Design::global();
    let env = crate::admin::templating::env();
    let body = match env.get_template("auth/login.html").and_then(|tmpl| {
        tmpl.render(minijinja::context! {
            design => minijinja::context! {
                project_name => design.project_name.as_str(),
                logo_initial => design.logo_initial.as_str(),
            },
            email => email.unwrap_or(""),
            error => error,
        })
    }) {
        Ok(html) => html,
        Err(err) => {
            eprintln!("admin login template render failed: {err}");
            login_page_fallback(&design.project_name, email, error)
        }
    };

    let resp = hyper::Response::builder()
        .status(status)
        .header("content-type", "text/html; charset=utf-8")
        .body(Full::new(Bytes::from(body)))
        .expect("valid response");
    with_admin_headers(resp)
}

/// Emergency login page used when the template engine can't render
/// `auth/login.html`. Deliberately self-contained — no CSS links, no
/// includes, no `env()` call — so a broken template environment still
/// lets an operator sign in and fix it.
fn login_page_fallback(project_name: &str, email: Option<&str>, error: Option<&str>) -> String {
    let project = escape_html(project_name);
    let email = email.map(escape_html).unwrap_or_default();
    let error_block = match error {
        Some(msg) => format!(r#"<p style="color:#b91c1c">{}</p>"#, escape_html(msg)),
        None => String::new(),
    };
    format!(
        r#"<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Sign in · {project}</title></head><body style="font-family:system-ui;max-width:20rem;margin:4rem auto;padding:0 1rem">
<h1>Sign in</h1><p>{project}</p>{error_block}
<form method="post" action="/admin/login">
<p><label>Email<br><input type="email" name="email" value="{email}" autofocus required></label></p>
<p><label>Password<br><input type="password" name="password" required></label></p>
<p><button type="submit">Sign in</button></p>
</form></body></html>"#,
    )
}

/// Render the 403 page. Rendered via `minijinja` against
/// `auth/forbidden.html`; falls back to a minimal inline shell with
/// the same sign-out form if the template render fails.
fn forbidden_page(csrf: Option<&str>) -> Response {
    let design = design::Design::global();
    let env = crate::admin::templating::env();
    let body = match env.get_template("auth/forbidden.html").and_then(|tmpl| {
        tmpl.render(minijinja::context! {
            design => minijinja::context! {
                project_name => design.project_name.as_str(),
                logo_initial => design.logo_initial.as_str(),
            },
            csrf_token => csrf.unwrap_or(""),
        })
    }) {
        Ok(html) => html,
        Err(err) => {
            eprintln!("admin forbidden template render failed: {err}");
            forbidden_page_fallback(&design.project_name, csrf)
        }
    };
    let resp = hyper::Response::builder()
        .status(403)
        .header("content-type", "text/html; charset=utf-8")
        .body(Full::new(Bytes::from(body)))
        .expect("valid response");
    with_admin_headers(resp)
}

/// Emergency 403 shell used when `auth/forbidden.html` can't render.
/// Self-contained — no CSS link, no includes, so a broken template
/// still lets the operator sign out.
fn forbidden_page_fallback(project_name: &str, csrf: Option<&str>) -> String {
    let project = escape_html(project_name);
    let csrf_input_html = match csrf {
        Some(token) if !token.is_empty() => format!(
            r#"<input type="hidden" name="_csrf" value="{}">"#,
            escape_html(token)
        ),
        _ => String::new(),
    };
    format!(
        r#"<!doctype html><html lang="en"><head><meta charset="utf-8"><title>403 Forbidden · {project}</title></head><body style="font-family:system-ui;max-width:28rem;margin:4rem auto;padding:0 1rem;text-align:center">
<p>403 Forbidden</p><h1>You're signed in, but you don't have admin access.</h1>
<form method="post" action="/admin/logout">{csrf_input_html}<button type="submit">Sign out</button></form>
</body></html>"#,
    )
}

