    #[test]
    fn primary_rule_6_status_state_priority() {
        assert!(is_primary_column(&make_field(
            "status",
            FieldType::String,
            None,
        )));
        assert!(is_primary_column(&make_field(
            "state",
            FieldType::String,
            None,
        )));
        assert!(is_primary_column(&make_field(
            "priority",
            FieldType::I32,
            None,
        )));
        // Near-miss — not an exact match.
        assert!(!is_primary_column(&make_field(
            "priorities",
            FieldType::I32,
            None,
        )));
    }

